(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c55"]=[{"id":"00015025","register_sub_id":"101","register_pk":"529303","name":"下郷家住宅（千代倉本家）紅葉蔵","kana":"しもさとけじゅうたく（ちよくらほんけ）もみじくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区鳴海町字相原町27他","lat":35.07941667,"lng":136.95257222,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積91㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"23 - 0607","desc":"東海道鳴海宿中心部にある商家の調度品や文書用の蔵。敷地南西隅に建つ土蔵造二階建切妻造本瓦葺で東面に桟瓦葺下屋を付す。外壁は黒漆喰塗で腰は下見板張。二階は北面に神棚を備え太い地棟に登梁形式の小屋をみせる。重厚な外観が商家の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015025"},{"id":"00004482","register_sub_id":"101","register_pk":"105472","name":"白井家住宅主屋","kana":"しらいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊川市国府町流霞157","lat":34.83607766,"lng":137.32465755,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積236㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0137","desc":"造り酒屋の主屋で，桁行８間梁行６間半と規模の大きいつし二階建で，切妻造，桟瓦葺の平入町家。街路に北面し，東端がトオリニワで，２列６室の居室を配し，落ち棟の仏間を介して西に新座敷が続く。正面に瓦葺下屋をつけて格子を建込み，２階は出格子とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004482"},{"id":"00014392","register_sub_id":"101","register_pk":"511381","name":"杉浦家住宅主屋","kana":"すぎうらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県西尾市一色町一色西屋敷44-1","lat":34.81031667,"lng":137.023975,"geo_status":"db","era":"江戸末期／大正10年頃・昭和61年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"23 - 0583","desc":"一色町中心部に建つ江戸期に遡る町家。二階建、切妻造平入桟瓦葺、南面して建つ。内部東は土間で太い梁を見せ、格子戸で前後に区切る。西は床上を整形六間取とし、大規模な農家型平面で、無目の差鴨居を用いる。仏間に仏壇部屋の上段を附属し、格式備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014392"},{"id":"00014393","register_sub_id":"101","register_pk":"511382","name":"杉浦家住宅書院","kana":"すぎうらけじゅうたくしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県西尾市一色町一色西屋敷44-1","lat":34.810325,"lng":137.02385833,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"23 - 0584","desc":"主屋の西側に接続して建つ接客用の座敷棟。平屋建で一〇畳二間を東西に並べて縁を付す。西の上の間床構えは床脇に違い棚を設け、床柱は杉の磨き丸太を用い、四周に内法長押を廻して室境に板欄間を嵌めるなど、主屋の仏間とは異なった趣を見せる近代和風。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014393"},{"id":"00006858","register_sub_id":"101","register_pk":"107840","name":"鈴木家住宅蔵","kana":"すずきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県愛西市須依町郷577他","lat":35.154629,"lng":136.717178,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0286","desc":"主屋の西側に連続して建つ。南面する２階建土蔵で、切妻造桟瓦葺とし、南面に下屋を設け蔵前とする。桁行４間梁間２間半で、南面東寄りに両開戸をたて、妻面に庇付窓を開ける。内部は板床で、壁竪板張とする。蔵前は梁間１間で、外観に重厚感を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006858"},{"id":"00006859","register_sub_id":"101","register_pk":"107841","name":"鈴木家住宅米蔵","kana":"すずきけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県愛西市須依町郷577他","lat":35.154243,"lng":136.717255,"geo_status":"db","era":"明治中期／昭和前期移築増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積81㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0287","desc":"主屋の南方、門の奥に東西棟で建つ２階建土蔵。切妻造妻入桟瓦葺で、東面から北面にかけて下屋庇をまわす。東側下屋は、側面に土壁、東面に竪格子を設けて、蔵前とする。妻面の窓に設けられた庇は漆喰仕上げで、持送りに絵様が施される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006859"},{"id":"00010786","register_sub_id":"101","register_pk":"201621","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市昭和区五軒家町20-2他","lat":35.142948,"lng":136.946884,"geo_status":"db","era":"昭和前期／昭和28頃改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋一部2階建、瓦葺、建築面積255㎡","structure_material":"木造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0429","desc":"山崎川の東岸、八事丘陵の住宅地に敷地を構える。平面は中廊下を軸として、座敷や台所等を配し、矩折に玄関棟を張出す。平屋建で整った意匠の座敷部や、二階建の洋室棟を複合するなど、戦前期の名古屋における、郊外型新興住宅地の様相を示す上質な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010786"},{"id":"00006969","register_sub_id":"101","register_pk":"107951","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県愛西市須依町郷577他","lat":35.154537,"lng":136.71727,"geo_status":"db","era":"Ｍ23／Ｔ後期改修・Ｓ前期増築改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階建、瓦葺、建築面積241㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0285","desc":"通りの西側に占める敷地の西北寄りに南面して建つ。桁行１６ｍ梁間１５ｍの２階建で、入母屋造桟瓦葺とし、四周に下屋をまわし、北面に寄棟屋根を突出する。座敷飾りをもつ主室や広間、仏堂風のつくりになる仏間、数寄屋造の茶室など見応えのある室空間になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006969"},{"id":"00006860","register_sub_id":"101","register_pk":"107842","name":"鈴木家住宅門及び外塀","kana":"すずきけじゅうたくもんおよびそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県愛西市須依町郷577他","lat":35.15416813,"lng":136.71736044,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 石造門柱2基、間口3.2m、両脇門付 塀 コンクリート造、延長77m","structure_material":"門 石造門柱2基","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0288","desc":"通りから少し入った位置に、東面して石造の門柱を構え、両脇に脇門を設ける。間口３．２ｍで、門柱は方０．４０ｍの花崗岩製になり、高さ２．５ｍ。脇門柱はやや小さくコンクリート造。塀はコンクリート造で、江戸切仕上げ風に目地を切り、棟に切石を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006860"},{"id":"00004246","register_sub_id":"101","register_pk":"105236","name":"髙木家住宅蔵","kana":"たかぎけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券73他","lat":35.38182982,"lng":136.93980014,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0140","desc":"主屋の背後，裏庭の東に位置する。桁行３間梁間２間の土蔵造２階建，切妻造，桟瓦葺の東西棟である。外壁は白漆喰仕上で，腰を海鼠壁とする。西妻に瓦葺庇をつけて戸口を開き，両開の黒漆喰塗土戸を釣込む。２階窓は片開の漆喰塗土戸を釣込み，瓦庇をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004246"},{"id":"00004245","register_sub_id":"101","register_pk":"105235","name":"髙木家住宅茶室","kana":"たかぎけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券73他","lat":35.38185254,"lng":136.939696,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0139","desc":"裏庭の北寄りに位置し，濡れ縁で主屋に接続する。屋根は切妻造，桟瓦葺で銅板葺の庇をつけ，濡れ縁を巡らす。柱は磨丸太である。茶室は４畳半台目で，東に洞口のある台目幅の床を設け，西面と南面に下地窓を開く。東に３畳室が続き，庇下に水屋を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004245"},{"id":"00004579","register_sub_id":"101","register_pk":"105569","name":"瀧川家住宅主屋","kana":"たきがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字中ケ谷4","lat":34.94105976,"lng":137.53818731,"geo_status":"db","era":"文化11／明治2移築","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積125㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0183","desc":"旗本設楽氏の陣屋を移築したもの。裏山中腹の，東西に長い敷地のやや東寄りに南面して建つ。平屋，桟瓦葺（もと茅葺）で，表側２間続きの座敷を中心に，裏に納戸をとり，東側に大きな地炉のある土間，台所等を配する。数少ない旗本陣屋の姿を伝えていて貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004579"},{"id":"00004580","register_sub_id":"101","register_pk":"105570","name":"瀧川家住宅長屋門","kana":"たきがわけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字中ケ谷4","lat":34.94093228,"lng":137.53819776,"geo_status":"db","era":"宝暦13","year":1763,"year_source":"db","year_min":1763,"year_max":1763,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0184","desc":"主屋の南方に建つ。桁行６間半，梁間２間，切妻造，桟瓦葺で，西寄りに鏡柱を立て脇戸付の戸口を開き，両脇に大小２部屋を取り，西面に下屋を付す。部屋内部は改造されているが戸口廻り，正面の武者窓等の構えはよく残り，旗本代官屋敷としての家格を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004580"},{"id":"00004581","register_sub_id":"101","register_pk":"105571","name":"瀧川家住宅祠","kana":"たきがわけじゅうたくほこら","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字中ケ谷4","lat":34.94120411,"lng":137.53769917,"geo_status":"db","era":"大永5／大正15移築","year":1525,"year_source":"db","year_min":1525,"year_max":1525,"year_label":null,"structure":"石造、面積0.1㎡","structure_material":"石造","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0185","desc":"敷地の西端部にある。自然石を積上げた台座上に置かれ，基礎，龕部，屋根を各１石で造り，龕部は内部に仏像を彫り出し，屋根は照り起りの寄棟造で，正面に軒唐破風を付す。観音開きの扉も石で造る。鳳来寺峯薬師如来を祀るといい，屋敷構えに欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004581"},{"id":"00004258","register_sub_id":"101","register_pk":"105248","name":"瀧野家住宅蔵","kana":"たきのけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券34","lat":35.38222157,"lng":136.9392026,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0152","desc":"主屋の西，裏庭を挟んで敷地北西隅に位置する。土蔵造２階建の東西棟で，桁行３間梁間２間半。切妻造，桟瓦葺で，東と南に１間幅の庇をつける。外壁は腰が海鼠壁とした白漆喰仕上で，２階を金属板で覆う。戸口は南面で両開土戸とし，２階窓には瓦庇をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004258"},{"id":"00012546","register_sub_id":"101","register_pk":"367841","name":"爲三郎記念館爲春亭","kana":"ためさぶろうきねんかんいしゅんてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市千種区掘割町一丁目9","lat":35.162659,"lng":136.977615,"geo_status":"geocoded","era":"昭和9年／平成7年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋一部地下１階建、瓦葺、建築面積325㎡","structure_material":"木造平屋一部地下１階建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0517","desc":"市東部の覚王山地区にある実業家旧別邸の主屋で、敷地東寄りに東面して建つ。南西側を懸造で庭園に張出す外観は変化に富む。内部は南側に座敷２室と茶室を雁行に配し、中庭を介して北側に居室を設ける。数寄屋基調の端正な意匠でまとめた良質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012546"},{"id":"00012550","register_sub_id":"101","register_pk":"367845","name":"爲三郎記念館正門","kana":"ためさぶろうきねんかんせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市千種区掘割町一丁目9","lat":35.162659,"lng":136.977615,"geo_status":"geocoded","era":"昭和前期／平成7年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺及び檜皮葺、間口1.6m、左右袖塀付","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0521","desc":"敷地南面の街路からやや奧に開く門。入母屋造桟瓦葺、縁辺部檜皮葺で、左右に袖塀を付す。本柱と控柱は節付丸太、柱間は土壁、天井は鏡天井、垂木は磨き丸太を扇に疎らに配る。野趣に富むつくりに板扉の花狭間等の意匠を加え、表構えを華やかに演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012550"},{"id":"00012549","register_sub_id":"101","register_pk":"367844","name":"爲三郎記念館雪隠","kana":"ためさぶろうきねんかんせっちん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市千種区掘割町一丁目9","lat":35.162659,"lng":136.977615,"geo_status":"geocoded","era":"昭和前期／平成7年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、杉皮葺、建築面積1.8㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0520","desc":"敷地北辺の待合西側に建つ砂雪隠。桁行一間梁間一間、片流れで招屋根付の杉皮葺で、丸太垂木木舞打の化粧屋根裏とする。西面に戸口を設け、東面と庭園側の南面中央に下地窓を穿つ。待合とともに庭園後方の落ち着いた景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012549"},{"id":"00012547","register_sub_id":"101","register_pk":"367842","name":"爲三郎記念館知足庵","kana":"ためさぶろうきねんかんちそくあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市千種区掘割町一丁目9","lat":35.162659,"lng":136.977615,"geo_status":"geocoded","era":"昭和11年頃／平成7年移築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0518","desc":"爲春亭西北端に接続していた茶室で、現在は庭園西辺に移り、独立して建つ。如庵に想を得た二畳半台目を基本とするが、床の間を台形、点前座を落天井とし、躙口を床の間正面に構えるなど創意ある意匠で整える。良材を用いた端正な構えで独特の趣を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012547"},{"id":"00012551","register_sub_id":"101","register_pk":"367846","name":"爲三郎記念館東門","kana":"ためさぶろうきねんかんひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市千種区掘割町一丁目9","lat":35.162659,"lng":136.977615,"geo_status":"geocoded","era":"昭和前期／平成7年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、こけら葺、間口1.2m、左右袖塀付","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0522","desc":"敷地東面の街路からやや奥の石段上に開く門。切妻造の腕木門で、左右に袖塀を付す。間口１・２メートルで本柱を立て、肘木付腕木で軒桁を受け、疎垂木とする。小規模ながら、磨き丸太の軒桁や垂木、こけら葺屋根の数寄屋意匠が閑静な佇まいを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012551"},{"id":"00012548","register_sub_id":"101","register_pk":"367843","name":"爲三郎記念館待合","kana":"ためさぶろうきねんかんまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市千種区掘割町一丁目9","lat":35.162659,"lng":136.977615,"geo_status":"geocoded","era":"昭和前期／平成7年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、杉皮葺、建築面積2.6㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0519","desc":"敷地北辺の西寄りに建つ茶室知足庵の待合。桁行二間梁間一間、杉皮葺、片流れの招屋根付で、疎垂木で深い軒をつくる。南の庭園に向けて開放し、爲春亭側の東面に下地窓を穿つ。節付丸太を用いるなど野趣に富んだつくりで、庭園景観に趣を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012548"},{"id":"00007052","register_sub_id":"101","register_pk":"108034","name":"どうだん亭（旧浅井家住宅離れ）","kana":"どうだんてい（きゅうあさいけじゅうたくはなれ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県尾張旭市霞ヶ丘町南298他","lat":35.211296,"lng":137.005341,"geo_status":"db","era":"昭和17／昭和42移築・平成9改修","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0303","desc":"敷地中央に建つ。建築面積８９㎡、木造２階建、切妻造桟瓦葺。飛騨市内に所在した享保８年建築の合掌造民家を移築したもので、急勾配の下屋屋根や室内のチョウナ梁に名残をとどめる。施主浅井竹五郎の数寄好みにより、山荘風の近代数寄屋建築にまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007052"},{"id":"00010155","register_sub_id":"101","register_pk":"197988","name":"徳川園黒門","kana":"とくがわえんくろもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区徳川町1001","lat":35.183966,"lng":136.931925,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造、瓦葺、間口3.6m、潜戸付","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0403","desc":"尾張徳川家名古屋本邸の正門として建設された。間口の広い三間薬医門形式で、軸部は木太いケヤキを用いる。左右に塀を接続し、北には脇長屋を従える。貴顕の本邸正面を飾るに相応しい堂々とした容姿で、現在は徳川園の正門として、黒門の愛称で親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010155"},{"id":"00010158","register_sub_id":"101","register_pk":"197991","name":"徳川園釣瓶井戸","kana":"とくがわえんつるべいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区徳川町1001","lat":35.183729,"lng":136.932079,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"石造、面積1.6㎡、屋形付","structure_material":"石造","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0406","desc":"脇長屋の北東方に位置する。かつてはこの横に厩舎と馬車置場が建っていた。井戸枠は花崗岩の切石を井桁に組む。傍らになぐり仕上の支柱を立て、破風板付の切妻屋根をかけて鉄製桜花文透の滑車を吊り、釣瓶を備える。細部意匠まで気の配られた井戸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010158"},{"id":"00010157","register_sub_id":"101","register_pk":"197990","name":"徳川園塀","kana":"とくがわえんへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区徳川町1001","lat":35.1848215,"lng":136.93178576,"geo_status":"db","era":"明治33頃／平成16改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造、瓦葺、総延長84m、潜戸付","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0405","desc":"屋敷地の西辺を画す塀である。黒門を挟んで蘇山荘西入口に至る塀は、桟瓦葺で簓子下見板張及び漆喰塗とする。園内西側の傾斜地に三間幅で階段状に連ねる塀は、外面を押縁の竪板張、内面をスギ皮張割竹押さえとして仕様を違えている。街路景観に趣を与える塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010157"},{"id":"00010156","register_sub_id":"101","register_pk":"197989","name":"徳川園脇長屋","kana":"とくがわえんわきながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区徳川町1001","lat":35.183812,"lng":136.931919,"geo_status":"db","era":"明治33頃／昭和7・平成16改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0404","desc":"黒門の南側に塀を介して接続する。南北棟とし、桁行二〇メートルを測る長屋で、腰を簓子下見板張、上部を漆喰仕上とする。黒門側の北西隅に出格子窓を張出しており、門衛所としての機能を持っていたことがわかる。重厚な外観が歴史的な風致を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010156"},{"id":"00010162","register_sub_id":"101","register_pk":"197995","name":"徳川美術館心空庵及び餘芳軒","kana":"とくがわびじゅつかんしんくうあんおよびよほうけん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県名古屋市東区徳川町1017","lat":35.183959,"lng":136.933834,"geo_status":"db","era":"心空庵 大正3／大正3・昭和6・昭和37移築 餘芳軒 昭和中期／昭和48移築","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0410","desc":"四畳半本勝手の茶室心空庵と、その東側の十畳広間を中心とした餘芳軒からなる。心空庵は茶室に三畳の水屋と矩折の腰掛待合を付ける。材木商を営んだ大寶正鑑の設計になり、霧島スギや神代材などの銘木や奇木を多用する。数寄屋の趣向を凝らした近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010162"},{"id":"00010161","register_sub_id":"101","register_pk":"197994","name":"徳川美術館山の茶屋","kana":"とくがわびじゅつかんやまのちゃや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区徳川町1017","lat":35.184198,"lng":136.933588,"geo_status":"db","era":"明治16／明治27移築・昭和23・昭和34改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積96㎡、供待付","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0409","desc":"上段の間と中段の間を置く東西棟と、下段の間と茶室を置く南北棟を矩折に接続する。東西棟は面皮柱、南北棟はスギの四方柾柱を多用するほか、掛込天井や砂壁、下地窓を採用し、部屋の隅を斜めに切るなど数寄屋の好みを表現する。大名庭園の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010161"},{"id":"00010163","register_sub_id":"101","register_pk":"197996","name":"徳川美術館餘芳軒東屋","kana":"とくがわびじゅつかんよほうけんあずまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市東区徳川町1017","lat":35.18418,"lng":136.933438,"geo_status":"db","era":"昭和中期／昭和48・昭和62移築","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造平屋建、銅板葺、建築面積7.5㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0411","desc":"九尺四方の方形平面で、隅柱を出節丸太とし、皮付丸太の間柱を立てる。軒は化粧屋根裏で、皮付小丸太を扇状に配して傘天井とし、方形造の屋根を軽快に架ける。内部は東側面に腰掛を置くのみの簡素な設えで、雅客の腰掛待合として供される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010163"},{"id":"00013258","register_sub_id":"101","register_pk":"366247","name":"冨田家住宅土蔵","kana":"とみたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県岡崎市本宿町字南中町23","lat":34.89021111,"lng":137.26103056,"geo_status":"db","era":"明治9年／平成30年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造二階建一部平屋建、瓦葺、建築面積43㎡","structure_material":"木造二階建一部平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"23 － 0547","desc":"敷地南西の木南舎背面にある南北棟で、南の家財蔵と北の米蔵からなる。いずれも切妻造桟瓦葺で、鉢巻を廻す。家財蔵は東に、米蔵は北に戸口を開き、それぞれ戸前に下屋を付す。外壁は下見板張で、家財蔵２階は漆喰塗とする。屋敷構えの一角を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013258"},{"id":"00013257","register_sub_id":"101","register_pk":"366246","name":"冨田家住宅木南舎","kana":"とみたけじゅうたくもくなんしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県岡崎市本宿町字南中町23","lat":34.89016667,"lng":137.26116111,"geo_status":"db","era":"文政10年（1827）／明治前期・平成30年改修","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造2階建、瓦葺、建築面積204㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"23 － 0546","desc":"旧東海道が縦貫する本宿町にある幕末まで陣屋代官を務めた医師の住宅。木南舎は代官屋敷の旧主屋で東面して建つ。切妻造の棟に越屋根を載せ、背面の屋根を下屋まで葺下ろし、四周に下屋を廻す。内部は北を土間、南を床上とする。代官屋敷の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013257"},{"id":"00014160","register_sub_id":"101","register_pk":"508790","name":"中村家住宅主屋","kana":"なかむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊川市篠束町大堀63-1他","lat":34.80438333,"lng":137.368075,"geo_status":"db","era":"天保14年(1843)／昭和3年頃増築","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造2階建一部地下付、瓦葺、建築面積241㎡","structure_material":"木造2階建一部地下付","registered":"2022.02.17(令和4.02.17)","register_no":"23-0565","desc":"伊那街道に南面する農家主屋。つし２階建、切妻造桟瓦葺で四周下屋を廻す。東は土間で竈と桑の地下貯蔵場を設け、西は３列９室で南西を床付座敷とする。当初から瓦葺とみられ、成の高い小壁等、江戸期ながら発達した様相を示す。街道の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014160"},{"id":"00011711","register_sub_id":"101","register_pk":"210727","name":"中村公園豊頌軒","kana":"なかむらこうえんほうしょうけん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県名古屋市中村区中村町字高畑","lat":35.174652,"lng":136.853963,"geo_status":"db","era":"明治前期／昭和32年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0481","desc":"稲沢市祖父江町にあった表千家十一代家元碌々斎好みの茶席を移築。木造平屋建、切妻造桟瓦葺で、銅板葺の庇を深く張り出す。本席は四畳半台目、本勝手の上座床。本席を中心に西側に水屋、北側に玄関、北東に二畳台目の寄付を配す。簡明で洗練された意匠の茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011711"},{"id":"00009609","register_sub_id":"101","register_pk":"194605","name":"名古屋市東山荘主屋","kana":"なごやしとうざんそうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市瑞穂区初日町2-3","lat":35.13489738,"lng":136.94354243,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋一部2階建、瓦葺、建築面積357㎡、北面門付","structure_material":"木造平屋一部2階建","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0373","desc":"回遊式の日本庭園の中に建築された大規模な別荘建築。前館、中館、後館からなり、格調を備えた書院座敷、洋風の応接間のほか、仰西庵、東丘庵といった複数の茶室を配し、後館は二階建で懸造風とする。複雑で変化に富む外観をもつ、良質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009609"},{"id":"00009610","register_sub_id":"101","register_pk":"194606","name":"名古屋市東山荘正門及び塀","kana":"なごやしとうざんそうせいもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市瑞穂区初日町2-3","lat":35.13469513,"lng":136.94390886,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"正門 木造、茅葺、間口3.0m 塀 木造、銅板葺、総延長32m","structure_material":"正門 木造","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0374","desc":"敷地南東隅に構える正門。間口三メートル、入母屋造茅葺で、左右に折曲がりに塀をのばす。本柱と控柱に節付丸太を使い、丸太垂木を扇に配る。塀は腰高にひしぎ竹を詰張し、漆喰塗小壁に横長の窓を透かす。数寄屋風を基調とし野趣と風格を備えた表門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009610"},{"id":"00009611","register_sub_id":"101","register_pk":"194607","name":"名古屋市東山荘庭門及び塀","kana":"なごやしとうざんそうにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市瑞穂区初日町2-3","lat":35.13472011,"lng":136.94372565,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"庭門 木造、杉皮葺、間口1.2m 塀 木造、鉄板葺、総延長19m","structure_material":"庭門 木造","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0375","desc":"主屋南東隅から矩折れにのばす塀の中ほどに、庭門を開く。庭門は腕木門、切妻造杉皮葺である。塀は正門と同様に腰高にひしぎ竹張とし、内庭側は杉板を張り、小壁に横長の窓を穿ち、鉄板葺とする。前庭と内庭を緩やかに区画する門塀で、庭空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009611"},{"id":"00016393","register_sub_id":"101","register_pk":"536460","name":"野々垣家住宅主屋","kana":"ののがきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字北古券22-3","lat":35.38545556,"lng":136.93805833,"geo_status":"db","era":"昭和9年／平成8年頃改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"23 - 0620","desc":"犬山城南方に位置する神社宮司の住宅の主屋。敷地中央に南面する２階建切妻造平入桟瓦葺で、二階正面に手摺を付す。東に玄関土間及び廊下、西に各階２室を並べ、一階北西室に神棚を配する。ガラス窓を多用した外観が時代相を示し、地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016393"},{"id":"00002044","register_sub_id":"101","register_pk":"103034","name":"羽田八幡宮社務所離れ（旧羽田野家住宅主屋）","kana":"はだはちまんぐうしゃむしょはなれ（きゅうはだのけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市花田町字斉藤56-3","lat":34.76495472,"lng":137.376609,"geo_status":"db","era":"江戸中期／大正末期移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"23 － 0050","desc":"図書館の先駆とされる羽田八幡宮文庫を主宰した神主の住宅主屋。文化９年(1812)に渥美半島の百々村から移築，さらに大正末年に現在地に移築された。木造平屋建，片入母屋造，桟瓦葺で，南面縁側の先に土庇を設ける。１０畳主室の床棚構成に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002044"},{"id":"00016390","register_sub_id":"101","register_pk":"536457","name":"春田家住宅主屋","kana":"はるたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市東区主税町三丁目6-2他","lat":35.18135556,"lng":136.91577778,"geo_status":"db","era":"大正13年／平成12年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積204㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"23 - 0617","desc":"名古屋城東方の住宅地に位置する、もと陶磁器貿易商の主屋。敷地北側の洋館に和館を接続し、いずれも２階建桟瓦葺。洋館は南面にベランダを付し、一階は折上天井の応接間、二階に床構え付き座敷など表向きの部屋を配す。和洋の意匠を巧みに用いた端正な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016390"},{"id":"00016391","register_sub_id":"101","register_pk":"536458","name":"春田家住宅門及び塀","kana":"はるたけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市東区主税町三丁目6-2他","lat":35.18112778,"lng":136.91580556,"geo_status":"db","era":"大正13年頃／平成12年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"門 木造、瓦葺、間口3.8m 塀 木造、瓦葺、総延長20m","structure_material":"門 木造","registered":"2025.11.17(令和7.11.17)","register_no":"23 - 0618","desc":"主屋の正面、通りに南面する門及び塀。門は通りより控えて建つ切妻造平入桟瓦葺の腕木門で門口に両引戸を建て、上部は吹寄の襷桟欄間とする。塀は切石基礎に建つ総延長２０メートルの板塀で外面漆喰塗で腰は竪板張。門と一体で屋敷の風格ある表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016391"},{"id":"00006585","register_sub_id":"101","register_pk":"107568","name":"萬乗醸造土蔵","kana":"ばんじょうじょうぞうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.06493,"lng":136.933823,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積93㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0242","desc":"敷地の東北隅に建つ桁行６間，梁間２間，南北棟，切妻造，桟瓦葺の２階建土蔵と，主屋東面に接続する桁行４間半，梁間３間，東西棟，切妻造，桟瓦葺，木造平屋建の蔵前部からなる。土蔵は腰簓子下見板張・上部黒漆喰塗，蔵前部は黒漆喰塗で通りの景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006585"},{"id":"00006584","register_sub_id":"101","register_pk":"107567","name":"萬乗醸造離れ","kana":"ばんじょうじょうぞうはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.06512388,"lng":136.93365228,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0241","desc":"主屋北西の８畳座敷の西に続く１０畳座敷と，西南方の３畳半茶室からなる。１０畳座敷は北西隅に残月亭写しの２畳の上段床を設けており，茶室は４畳半の規模で小振りな床の前と脇に板を嵌めた独特な床構えをもつ。ともに良質で凝ったつくりの近代数寄屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006584"},{"id":"00010159","register_sub_id":"101","register_pk":"197992","name":"蓬左文庫旧書庫","kana":"ほうさぶんこきゅうしょこ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区徳川町1001","lat":35.183563,"lng":136.932345,"geo_status":"db","era":"昭和10／平成16移築改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造一部鉄筋コンクリート造2階建、瓦葺、建築面積230㎡","structure_material":"木造一部鉄筋コンクリート造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0407","desc":"木造二階建で、吉本与志雄の設計により、もと敷地内にあった二棟の土蔵を接続して一棟の什器庫としたもの。小屋はキングポストトラスとし、外壁は屋根野地までモルタル塗としている。尾張徳川家に伝来した書物を収める蓬左文庫の書庫として長く使われた建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010159"},{"id":"00007359","register_sub_id":"101","register_pk":"108341","name":"寳泉寺書院（旧服部家住宅書院）","kana":"ほうせんじしょいん（きゅうはっとりけじゅうたくしょいん）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県津島市池麩町2","lat":35.17774573,"lng":136.72650141,"geo_status":"db","era":"明治期／昭和5移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"23 － 0310","desc":"境内北東隅に位置し、南側の庭園を挟んで建つ本堂や庫裏と廊下で繋ぐ。桁行１５ｍ梁間６．１ｍ規模、木造平屋建、入母屋造桟瓦葺。座敷と次の間、茶室の３室を東西に並べ、三方に縁をまわす。面皮柱や磨き丸太の長押を用いるなど、丁寧なつくりの数寄屋風書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007359"},{"id":"00005471","register_sub_id":"101","register_pk":"106459","name":"堀部家住宅作業場","kana":"ほりべけじゅうたくさぎょうば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券272","lat":35.378677,"lng":136.939804,"geo_status":"db","era":"明治26頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"23 － 0218","desc":"土蔵の東に接続する切妻造，桟瓦葺の木造平屋建。桁行３間半，梁間２間の物置に，落棟で桁行３間，梁間２間の農作業小屋が接続し，これに桁行３間，梁間２間の蚕室を並置する。外壁は真壁造の白漆喰塗りで，腰を下見板張りとする。同家の生業を示す遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005471"},{"id":"00005467","register_sub_id":"101","register_pk":"106455","name":"堀部家住宅主屋","kana":"ほりべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券272","lat":35.378891,"lng":136.939575,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造2階建、瓦葺、建築面積196㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"23 － 0214","desc":"北側道路に沿って建つ木造２階建で，切妻造，桟瓦葺の平入である。桁行９間半，梁間４間で，表と裏に瓦葺半間の下屋がつく。南面西端には水屋が付属する。内部は西に土間と台所，東に六間取の居室を配す。２階は座敷２室の他は物置とし，養蚕を行ったと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005467"},{"id":"00005472","register_sub_id":"101","register_pk":"106460","name":"堀部家住宅高塀","kana":"ほりべけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券272","lat":35.37896266,"lng":136.93960617,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、延長22m","structure_material":"木造","registered":"2006.03.27(平成18.03.27)","register_no":"23 － 0219","desc":"敷地の北辺，主屋の前面に並行する木造の塀である。折曲がり延長２２ｍで瓦屋根を葺く。玉石積の基礎上に建ち，要所に控柱を添える。外面は腰に波形鉄板張り，内面は土壁中塗仕上げとする。主屋との間は１間半幅の前庭とする。重厚な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005472"},{"id":"00005470","register_sub_id":"101","register_pk":"106458","name":"堀部家住宅土蔵","kana":"ほりべけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券272","lat":35.3786666,"lng":136.93964508,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"23 － 0217","desc":"敷地の中央に建つ，桁行４間半，梁間２間半の土蔵造２階建で，切妻造，桟瓦葺とする。北側に片引戸の戸口２箇所を設け，１間幅の瓦葺庇をつける。外壁は漆喰塗で，軒下まで押縁下見板張で養生する。内部は西から２間位置で間仕切りする。小屋組は登り梁である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005470"},{"id":"00005468","register_sub_id":"101","register_pk":"106456","name":"堀部家住宅離座敷","kana":"ほりべけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券272","lat":35.37879567,"lng":136.93966038,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"23 － 0215","desc":"主屋の南面東端に接続する木造平屋建で，桁行５間，梁間２間半の入母屋造，桟瓦葺とする。床，棚を備えた８畳座敷と押入を取り込んだ次の間７畳からなる。西面から南面へ縁を巡らせ，ガラス障子を建て込み，ガラス欄間を設ける。近代和風建築の一例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005468"},{"id":"00005469","register_sub_id":"101","register_pk":"106457","name":"堀部家住宅渡り廊","kana":"ほりべけじゅうたくわたりろう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券272","lat":35.37880697,"lng":136.93951024,"geo_status":"db","era":"明治26頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"23 － 0216","desc":"主屋南面西端の水屋から敷地西辺に沿って南の土蔵前まで延びる。桁行９間，梁間７尺規模，片流れ屋根の桟瓦葺である。敷地外側の壁上部は波板鉄板張で，腰を押縁下見板張とする。内部には物置，便所，風呂等を配し，敷地内側に設けた土庇下を通路とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005469"},{"id":"00014838","register_sub_id":"101","register_pk":"519098","name":"間瀬家住宅（作右衛門屋敷）土蔵","kana":"ませけじゅうたく（さくえもんやしき） どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県半田市亀崎町六丁目83-1他","lat":34.91403333,"lng":136.96444444,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積35㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0592","desc":"主屋の西に廊下を介して接続する家財蔵。２階建切妻造桟瓦葺の東西棟で東を戸口とし、東妻に窓を１箇所開ける。外壁は軒まで塗込め、戸口に掛子塗扉を吊る。内部は各階１室の板敷で東南隅に階段を置く。窓少なく重厚な外観の土蔵で旧家の屋敷構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014838"},{"id":"00014837","register_sub_id":"101","register_pk":"519097","name":"間瀬家住宅（作右衛門屋敷）主屋","kana":"ませけじゅうたく（さくえもんやしき）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県半田市亀崎町六丁目83-1他","lat":34.91406944,"lng":136.96456389,"geo_status":"db","era":"明治17年頃／昭和7年増築、令和5年改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積194㎡","structure_material":"木造2階一部平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0591","desc":"師崎街道に面し、廻船問屋と材木商で栄えた商家の主屋。敷地中央に建つ二階建切妻造桟瓦葺の東西棟で西に落棟の座敷を接続。内部は東を玄関、床上に２列7室を並べ、南北に縁を付す。南西を主座敷とし、南縁の欄間を無双窓、戸袋を網代張など数寄屋風の意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014837"},{"id":"00002145","register_sub_id":"101","register_pk":"103135","name":"又兵衛（旧坂上家住宅）","kana":"またべえ（きゅうさかがみけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県名古屋市熱田区神宮1-1-1","lat":35.12513148,"lng":136.90828786,"geo_status":"db","era":"江戸中期／昭和11及び同32移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積124㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"23 － 0054","desc":"もと飛騨北東部の合掌造民家。入母屋造，平入の広間型平面で，下手にマヤとニワ，上手に仏間を挟んでデイとチョウダを前後に配する。股柱など構造形式からみて現存合掌造民家としては最古期に属し，城戸久調査指導による移築も最初期の民家移築保存例になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002145"},{"id":"00004560","register_sub_id":"101","register_pk":"105550","name":"真野家住宅主屋","kana":"まのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券57","lat":35.38079252,"lng":136.9394393,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積219㎡、渡り廊付","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0164","desc":"金融業を営んだ家で，名古屋へと至る主街道（中本町通り）に西面して建つ。２階建，切妻造，桟瓦葺で，１階は通り庭の北に座敷等を並べ，南に板の間，階段室等を配する。良材を用いた上質なつくりで，正面の木太い格子など犬山の伝統的町家形式をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004560"},{"id":"00004563","register_sub_id":"101","register_pk":"105553","name":"真野家住宅高塀","kana":"まのけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券57","lat":35.3807363,"lng":136.9399144,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造、瓦葺、延長29m","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0167","desc":"主屋裏の南渡廊下に続き敷地後半南側面を仕切る。切石の地覆上に建つ木造，屋根付の高塀で，軒を大きく塗り上げて桟瓦葺の屋根をかけ，表裏とも一段下に腕木で支えた出桁を通し小庇を設ける。高さ５ｍに及ぶ特徴ある塀で，重厚な屋敷構えに欠かせない建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004563"},{"id":"00004562","register_sub_id":"101","register_pk":"105552","name":"真野家住宅土蔵","kana":"まのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券57","lat":35.38077785,"lng":136.93983753,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積121㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0166","desc":"離座敷背後に棟を東西に通して建つ。土蔵造，２階建，切妻造，桟瓦葺で，内部は桁行に２分し，南面にそれぞれ戸口を開き，庇を付す。軒廻りは斜めに塗り上げるのみで戸口や窓の扉も掛子塗とせず簡素な造りだが，規模が大きく高塀越しに堂々とした姿を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004562"},{"id":"00004561","register_sub_id":"101","register_pk":"105551","name":"真野家住宅離座敷","kana":"まのけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券57","lat":35.38080128,"lng":136.9396559,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0165","desc":"主屋裏に中庭を挟んで建ち，南北の渡り廊で連絡する。平屋，北側切妻造，南側寄棟造，桟瓦葺で，床，違棚を持つ８畳の座敷と４畳の次の間からなり，西，南に縁を廻す。小規模ながら本格的な座敷飾を備え，身舎屋根を一段高く切り上げる等格式ある構えをもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004561"},{"id":"00004252","register_sub_id":"101","register_pk":"105242","name":"三井家住宅渡り廊","kana":"みついけじゅうたくわたりろう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券684","lat":35.38337811,"lng":136.94000982,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0146","desc":"主屋の南側，トオリニワから南へ延びる附属棟。桁行４間５尺梁間１間２尺規模の平屋建で，片流屋根を桟瓦葺とする。西辺に土間が通り，東北の一郭を浴室，東南の一郭を便所とする。腰壁のコンクリートブロックは後の補修である。裏庭側景観の一要素をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004252"},{"id":"00014167","register_sub_id":"101","register_pk":"508797","name":"三宅家住宅主屋","kana":"みやけけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県尾張旭市西大道町五輪塚3676","lat":35.21311667,"lng":137.03086667,"geo_status":"db","era":"明治前期／昭和23年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積210㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"23-0572","desc":"瀬戸街道沿いの在郷町で紺屋業と酒造業を営んだ商家の主屋。街道とは前庭を挟む。入母屋造桟瓦葺平入、つし二階風の窓を設け、真壁造漆喰塗とし、深い下屋を四方に張出す。平面は六間取の農家型で、太い梁組の土間には藍瓶を埋設し、かつての生業を窺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014167"},{"id":"00014168","register_sub_id":"101","register_pk":null,"name":"三宅家住宅蔵","kana":"みやけけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県尾張旭市西大道町五輪塚3676","lat":35.21328611,"lng":137.03075278,"geo_status":"db","era":"明治前期／令和元年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"23-0573","desc":"瀬戸街道沿い在郷商家の道具蔵。敷地西辺の主屋後方に位置する。土蔵造二階建、切妻造桟瓦葺平入、東面戸口土庇付、外壁は鉢巻付、モルタル仕上で腰を黒色とする。一階は二室に区切り、二階は一室で西面に窓を備える。小屋組は牛梁に角材の登り梁を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014168"},{"id":"00014169","register_sub_id":"101","register_pk":"508799","name":"三宅家住宅庭門及び塀","kana":"みやけけじゅうたくにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県尾張旭市西大道町五輪塚3676-1","lat":35.21305,"lng":137.03086111,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、瓦葺、間口1.4m 塀 木造、瓦葺、総延長30m","structure_material":"門 木造","registered":"2022.02.17(令和4.02.17)","register_no":"23-0574","desc":"瀬戸街道の在郷商家の庭門と塀。庭門は東面し、主屋正面で座敷前庭を画す。切妻造桟瓦葺腕木門、両開板戸を建て、袖塀を付す。塀は庭門袖塀南端から、街道沿いに西へ延ばし、北へ折れて敷地西辺を囲む。真壁造桟瓦葺で腰板張。街道沿いの景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014169"},{"id":"00005886","register_sub_id":"101","register_pk":"106871","name":"宮田家住宅井戸屋形","kana":"みやたけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券719","lat":35.38436797,"lng":136.94066969,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"23 － 0231","desc":"敷地の西北隅，蔵の西方に位置し，東西棟で建つ。桁行４．４ｍ，梁間２．４ｍ規模，切妻造，桟瓦葺で，柱は内転びとし，軸部は地覆と貫で固める。軒は一軒疎垂木で，地棟の東寄りに滑車を吊る。簡素なつくりであるが，屋敷構えの景観に欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005886"},{"id":"00005885","register_sub_id":"101","register_pk":"106870","name":"宮田家住宅蔵","kana":"みやたけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券719","lat":35.384369,"lng":136.940735,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"23 － 0230","desc":"敷地の西北隅部に位置する。桁行４間，梁間２間半規模，切妻造，桟瓦葺の２階建土蔵で，南面に１間半の下屋を差し掛けて蔵前をとり，戸口には金庫風扉を吊る。小屋組は和小屋と登梁を併用し，外壁腰には舟板を張る。基礎は「ごんぼ積」と称する玉石の亀甲積。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005885"},{"id":"00005884","register_sub_id":"101","register_pk":"106869","name":"宮田家住宅對依軒","kana":"みやたけじゅうたくたいいけん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券719","lat":35.38422,"lng":136.94104,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"23 － 0229","desc":"表千家の久田無適齋宗也の構想と指導により，京数寄屋師高橋為吉が施工。玄関，取次，寄付，１０畳の次ノ間，１２畳の書院ノ間，雪隠等からなり，西面北寄りに「又隠」写しの４畳半茶室を突き出す。材料及び工法等，数寄屋普請の建築構成をもつ昭和初期の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005884"},{"id":"00005887","register_sub_id":"101","register_pk":"106872","name":"宮田家住宅塀","kana":"みやたけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券719","lat":35.38440387,"lng":136.94086351,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造、瓦葺、延長48m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"23 － 0232","desc":"塀は敷地西辺中央の正門及び旧物置の南方と北方に建ち，高塀は敷地西北角と北辺に建つ。塀は真壁造で，水路玉石護岸の上に建ち，腰を簓子下見板張とし，目板瓦の屋根を載せる。高塀は切石積基礎の上に建ち，桟瓦葺の小屋根を載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005887"},{"id":"00003654","register_sub_id":"101","register_pk":"104644","name":"明治村赤坂離宮正門哨舎","kana":"めいじむらあかさかりきゅうせいもんしょうしゃ","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.33979959,"lng":136.988297,"geo_status":"db","era":"明治41／昭和58移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積2.0㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0067","desc":"片山東熊設計の旧東宮御所正門内外に４基設けられた哨舎の１基。木造，八角平面。壁は内外とも白ペンキ塗で，半円アーチの出入口と円形小窓を開く。軒先には蛇腹，歯飾りと雷文を飾る。銅板葺の丸屋根頂部には巻軸飾りと花綱飾りを組合せ，頂部に球を載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003654"},{"id":"00003655","register_sub_id":"101","register_pk":"104645","name":"明治村学習院長官舎","kana":"めいじむらがくしゅういんちょうかんしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.33999128,"lng":136.98973013,"geo_status":"db","era":"明治42／昭和39移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0068","desc":"２階建の和館と洋館を接続した木造住宅建築。和館部は上下階とも床構えを持つ１０畳と６畳に縁と廊下が付く。洋館部は下見板張で胴蛇腹を廻し，欄間付上げ下げ窓を配す。２階窓は小庇と窓台に持送りが付く。玄関部に差掛けた車寄は鉄柱と妻飾りが軽快である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003655"},{"id":"00003667","register_sub_id":"101","register_pk":"104657","name":"明治村幸田露伴住宅蝸牛庵","kana":"めいじむらこうだろはんじゅうたくかぎゅうあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34091548,"lng":136.99290716,"geo_status":"db","era":"明治初／昭和47移築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積120㎡","structure_material":"木造平屋一部2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0080","desc":"木造一部２階建，寄棟造，桟瓦葺。外壁は押縁下見。玄関，台所，６畳２室の主体部に小さく２階を載せ，１０畳座敷部を接続する。複雑な平面に応じた変化のある屋根形状を呈する。座敷の切目縁は吹放ちで土庇の出が深い。中流住宅の当時を伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003667"},{"id":"00003674","register_sub_id":"101","register_pk":"104664","name":"明治村神戸山手西洋人住居主屋","kana":"めいじむらこうべやまてせいようじんじゅうきょしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34211538,"lng":136.99280421,"geo_status":"db","era":"明治20代／昭和44移築","year":1887,"year_source":"converted","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積73㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0087","desc":"木造２階建，寄棟造，桟瓦葺。正面と片側面に折廻したヴェランダを上下階に設け，竪溝付角柱を吹寄せに配す特徴がある。出入口は櫛形欄間付の両開戸で鎧戸が付く。内部は上下階とも階段のある中廊下の両側に各１室を配す。ヴェランダ・コロニアル住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003674"},{"id":"00003675","register_sub_id":"101","register_pk":"104665","name":"明治村神戸山手西洋人住居付属屋","kana":"めいじむらこうべやまてせいようじんじゅうきょふぞくや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34214234,"lng":136.99271558,"geo_status":"db","era":"明治20代／昭和44移築","year":1887,"year_source":"converted","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積36㎡、2階渡廊下付","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0088","desc":"木造２階建，寄棟造，桟瓦葺。主屋の背面に僅かに離れて建つ。外壁は柱形を表した下見板張。１階は土間と６畳和室，２階は縁の付く１０畳座敷と３畳室からなる。棟内には階段がなく，２階へは主屋２階との間の渡り廊下だけで接続する特異な平面をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003675"},{"id":"00003861","register_sub_id":"101","register_pk":"104851","name":"明治村シアトル日系福音教会","kana":"めいじむらしあとるにっけいふくいんきょうかい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34321841,"lng":136.99203096,"geo_status":"db","era":"明治40頃／昭和59移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、板葺、建築面積96㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0095","desc":"木造２階建，寄棟造，シングル葺で，両妻に屋根窓を載せる。我国へも明治末に導入されたプラットフォーム構法で，外壁は小口留の細かな下見板張とする。太い角柱で支えた玄関ポーチと２階ベイ・ウィンドウで変化をつけ，正面側の窓台は細かな持送りで受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003861"},{"id":"00006857","register_sub_id":"101","register_pk":"107839","name":"明治村芝川家住宅主屋","kana":"めいじむらしばかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市字内山1","lat":35.34139368,"lng":136.9922633,"geo_status":"db","era":"明治44／平成19移築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0284","desc":"博物館明治村内の高台に建つ。建築面積１６５㎡、木造２階建、瓦葺。１階は開放的なヴェランダにボウウィンドウを開くなど洋風とするが、２階は対照的に和風としつつ、両者を破綻なくまとめている。武田五一設計になる和洋意匠を折衷した住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006857"},{"id":"00003671","register_sub_id":"101","register_pk":"104661","name":"明治村茶室亦楽庵","kana":"めいじむらちゃしつえきらくあん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.341251,"lng":136.99330821,"geo_status":"db","era":"明治10頃／昭和46移築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0084","desc":"京都の医師，福井恒斎が自邸に建てた茶室である。木造平屋建，桁行２間半梁間３間。千宗旦の茶室「又隠」を模したといわれる四畳半茶室に，瓦敷き土間，水屋，廊下が付く。切妻造，桟瓦葺で，表側妻に小さな切妻屋根を付け，軒先，螻羽と庇を銅板葺とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003671"},{"id":"00003673","register_sub_id":"101","register_pk":"104663","name":"明治村長崎居留地二十五番館別館","kana":"めいじむらながさききょりゅうちにじゅうごばんかんべっかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.341923,"lng":136.992508,"geo_status":"db","era":"明治43／昭和41移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積120㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0086","desc":"木造平屋建，寄棟造，桟瓦葺。切石基礎で，外壁は柱形を表した下見板張。内部は中央洋室と床構えを備えた和室２室を組合せる。洋室の三方に巡らせた廊下は外壁に引違い窓を入れるが，洋室側壁面に両開き戸と上下げ窓を設けて半戸外的に扱うのが特徴である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003673"},{"id":"00003672","register_sub_id":"101","register_pk":"104662","name":"明治村長崎居留地二十五番館本館","kana":"めいじむらながさききょりゅうちにじゅうごばんかんほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34177155,"lng":136.99251659,"geo_status":"db","era":"明治22／昭和41移築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0085","desc":"木造平屋建，寄棟造，桟瓦葺で，正面と両側面に一段低く屋根を架けた板敷のヴェランダを巡らすコロニアル・スタイル。ヴェランダの角柱は礎石立で，柱頭の持送りが桁を受ける。隅柱を表した下見板張の外壁に両開き鎧戸付の上げ下げ窓を開く。棟梁は堤松太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003672"},{"id":"00003862","register_sub_id":"101","register_pk":"104852","name":"明治村ブラジル移民住宅","kana":"めいじむらぶらじるいみんじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34355976,"lng":136.99148831,"geo_status":"db","era":"大正8／昭和50移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0096","desc":"木造２階建，切妻造，スペイン瓦葺。日本人大工による真壁造の建物で，小屋組や継手も和風の技法とする。１階は煉瓦敷の台所と納屋，２階が居室４室で外階段がつく。２階ヴェランダは曲木で受ける。窓は片開き板戸と両開きガラス戸を部屋毎に使い分けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003862"},{"id":"00003656","register_sub_id":"101","register_pk":"104646","name":"明治村森鷗外・夏目漱石住宅","kana":"めいじむらもりおうがい・なつめそうせきじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34041459,"lng":136.99054713,"geo_status":"db","era":"明治20頃／昭和39移築","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0069","desc":"木造平屋建，寄棟造，桟瓦葺で，外壁は押縁下見板張。田の字型平面を基本とする和風住宅で，座敷の表に縁を通す。玄関脇に応接兼書斎を設け，台所から短い中廊下を設けるなど，近代住宅への萌芽も見える。明治中期の典型的中流住宅の姿を示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003656"},{"id":"00007212","register_sub_id":"101","register_pk":"108194","name":"森川家住宅主屋","kana":"もりかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県一宮市大和町苅安賀字北川田1159","lat":35.29066566,"lng":136.78185142,"geo_status":"db","era":"安政2／明治2改修","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"23 － 0305","desc":"街路に北面して建つ木造つし２階建の町家である。間口７間の平入で、切妻造桟瓦葺とし、正面に瓦葺庇が付く。正面１階は東に戸口を設け、西に格子を構える。２階は軒が出桁造で、両端に袖卯建、窓に格子を付ける。間口が大きく街路景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007212"},{"id":"00007213","register_sub_id":"101","register_pk":"108195","name":"森川家住宅書院","kana":"もりかわけじゅうたくしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県一宮市大和町苅安賀字北川田1159","lat":35.290611,"lng":136.781662,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"23 － 0306","desc":"主屋南側縁の西端に接続する、木造平屋建の離れ座敷である。桁行４間半梁間３間で、寄棟造桟瓦葺とし、庭に面した東面と南面には銅板葺庇の広縁が付く。座敷は二畳の上段を設けた十一畳半で、次の間十畳が続く。北面の下屋に茶室と水屋を付設する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007213"},{"id":"00007214","register_sub_id":"101","register_pk":"108196","name":"森川家住宅土蔵","kana":"もりかわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県一宮市大和町苅安賀字北川田1159","lat":35.29073076,"lng":136.78173252,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"23 － 0307","desc":"主屋西面に蔵前を介して接続する土蔵造２階建で、北側街路に妻を見せて建つ。桁行７．６ｍ梁間４．７ｍで、切妻造桟瓦葺。外壁は白漆喰仕上げで、高く下見板を張る。小屋組は登梁である。東の蔵前に戸口、南妻に庇付窓を開く。主屋とともに街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007214"},{"id":"00008495","register_sub_id":"101","register_pk":"134891","name":"山口家住宅表門","kana":"やまぐちけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県海部郡蟹江町城4-215","lat":35.13010641,"lng":136.79146972,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造、瓦葺、間口3.8m、塀付","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"23 － 0332","desc":"敷地南辺の東寄りに位置する。桁行三・八メートルの腕木門で、両脇に袖塀を付ける。中央に門口、東に潜りを開け、両開の板戸に吊り、軒を一軒疎垂木として、切妻造桟瓦葺の屋根をかける。両脇は腰板張の土壁とする。前庭の植栽とともに屋敷の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008495"},{"id":"00008493","register_sub_id":"101","register_pk":"134889","name":"山口家住宅主屋","kana":"やまぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県海部郡蟹江町城4-215","lat":35.13025929,"lng":136.79138564,"geo_status":"db","era":"江戸後期／明治期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺一部瓦葺、建築面積192㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"23 － 0330","desc":"敷地の中央東寄りに南面して建つ。桁行一四メートル梁間六・八メートル、入母屋造茅葺の上屋の四周に、桟瓦葺の下屋などを付設。東に土間、西に床上を配し、広間三間取型を基本に仏間等を張り出す平面とする。「四つ建」と呼ばれる尾張地方の伝統的な構造になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008493"},{"id":"00008494","register_sub_id":"101","register_pk":"134890","name":"山口家住宅茶室","kana":"やまぐちけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県海部郡蟹江町城4-215","lat":35.13021884,"lng":136.7912508,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積35㎡、中門、露地門及び塀付","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"23 － 0331","desc":"主屋の西南に建ち、主屋広縁に接続する。切妻造桟瓦葺。四畳半切の茶室と水屋を南北に配し、東に六畳の小間や便所を配する。トコ柱に面皮付桜材、框や柱に磨き丸太など銘木を用いる。トコ脇に風炉先窓、北面に躙り口や大きな障子窓を設ける開放感ある茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008494"},{"id":"00008298","register_sub_id":"101","register_pk":"133940","name":"赤井家住宅主屋","kana":"あかいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野忍町2491-1","lat":34.76309781,"lng":136.12870676,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0095","desc":"角地に占める敷地の中ほどに東面して建つ。建築面積１６０㎡、木造平屋建、切妻造桟瓦葺で、下屋をまわす。正面北寄りに構える玄関の南に台所、北に六畳を突出させ、後方を座敷とする。武家住宅であった前身建物の間取を継承した平面になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008298"},{"id":"00008299","register_sub_id":"101","register_pk":"133941","name":"赤井家住宅茶室","kana":"あかいけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊賀市上野忍町2491-1","lat":34.76297912,"lng":136.12877141,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0096","desc":"主屋の東南、土蔵との間に建ち、建築面積１２㎡、木造平屋建、切妻造銅板葺である。間取は三畳で庭に面した西面を貴人口として軒を差し出す。南面に円窓を穿ち、その東側に煤竹をトコ柱とするトコを備える。端正な佇まいで、豊かな露地空間を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008299"},{"id":"00008300","register_sub_id":"101","register_pk":"133942","name":"赤井家住宅土蔵","kana":"あかいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野忍町2491-1","lat":34.762955,"lng":136.12885054,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0097","desc":"屋敷地内の東南角地に建ち、桁行５．８ｍ梁間３．８ｍ、土蔵造２階建、切妻造桟瓦葺である。切石積基礎に建ち、腰高に竪板を張り、上部は白色の鉄板仮張とする。１階西面に出入口を設け、額縁を漆喰塗とし、絵様持送り付の庇をかけるなど、丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008300"},{"id":"00008302","register_sub_id":"101","register_pk":"133944","name":"赤井家住宅土塀","kana":"あかいけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野忍町2491-1他","lat":34.76290339,"lng":136.12856495,"geo_status":"db","era":"明治28年／昭和32年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土塀、瓦葺、総延長48m、木戸門付","structure_material":"土塀","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0099","desc":"敷地東面の長屋門から北側と、長屋門と土蔵の間、敷地南面の土蔵西側に建つ。総延長５４ｍ、高さ２ｍ内外、桟瓦葺で、南方土塀の中ほどには門を構える。切石積基礎上に築かれ、壁面は中塗仕上げとする。もと武家町らしい歴史的な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008302"},{"id":"00008301","register_sub_id":"101","register_pk":"133943","name":"赤井家住宅長屋門","kana":"あかいけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊賀市上野忍町2491-1","lat":34.76314509,"lng":136.12883703,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0098","desc":"表通りに東面して建ち、桁行１５ｍ梁間４．０ｍ、木造平屋建、入母屋造桟瓦葺で、南・西面に下屋を張り出す。北寄りに門口を構え、正面は簓子下見板張で上部を漆喰塗とし、南端に出格子窓を付ける。重厚な外観になり、上野城下で数少ない武家住宅の遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008301"},{"id":"00002266","register_sub_id":"101","register_pk":"103256","name":"伊勢河崎商人館内蔵一","kana":"いせかわさきしょうにんかんうちぐらいち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.4967577,"lng":136.71764302,"geo_status":"db","era":"天保年間","year":1836,"year_source":"estimated","year_min":1830,"year_max":1844,"year_label":"天保年間","structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0035","desc":"離れの北側に建ち，主に日用品等の収納に用いられていた土蔵で，天保年間の建設と考えられている。規模は桁行３間半，梁間２間半程度で，２階建，南北棟の切妻造・本瓦葺。西面に出入口を持ち，壁面は黒染の下見板張とする。近世の屋敷構を伝える要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002266"},{"id":"00002267","register_sub_id":"101","register_pk":"103257","name":"伊勢河崎商人館内蔵二","kana":"いせかわさきしょうにんかんうちぐらに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.49674923,"lng":136.717545,"geo_status":"db","era":"天保6","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積25㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0036","desc":"主屋の北側にあり，座敷から北に延びる廊下で結ばれている。２階建，南北棟の切妻造・本瓦葺で，衣装蔵に用いられてきた。南面に観音扉を構え，壁面は黒染の下見板張とする。棟木に天保６年の墨書があり，屋敷内で年代が判明している最古の建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002267"},{"id":"00002264","register_sub_id":"101","register_pk":"103254","name":"伊勢河崎商人館北蔵一","kana":"いせかわさきしょうにんかんきたぐらいち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.49694547,"lng":136.71759,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積97㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0033","desc":"敷地の北側に建ち，主に漬物製造に用いられていた土蔵。南側の平屋建の前室と北側の２階建の後室からなり，屋根は南北棟の切妻造・本瓦葺。北面には高い位置に２つの窓を持ち，壁面は下見板張とする。商家における多様な機能の一端を物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002264"},{"id":"00002260","register_sub_id":"101","register_pk":"103250","name":"伊勢河崎商人館離れ","kana":"いせかわさきしょうにんかんはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.49667721,"lng":136.71765823,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積15㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0029","desc":"伊勢河崎商人館の敷地は主屋の建つ南側が街路に面している。離れは敷地奥，主屋の北東にある。小規模な２階建の建物で，屋根は起りのある南北棟の切妻造・桟瓦葺とする。主屋とほぼ同時期の建設とみられ，商家における内向きの構成建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002260"},{"id":"00014617","register_sub_id":"101","register_pk":"515159","name":"乾家住宅門及び塀","kana":"いぬいけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県多気郡明和町大字斎宮字牛葉321-1他","lat":34.53648889,"lng":136.61615278,"geo_status":"db","era":"江戸後期／昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"門 木造、瓦葺、間口2.9m 塀 木造、瓦葺、総延長39m","structure_material":"門 木造","registered":"2023.08.07(令和5.08.07)","register_no":"24 - 0325","desc":"伊勢街道沿いの旧家の門及び塀。敷地北辺を区画する塀の中央に門を開き、門の内側西寄りに南北塀を設けて庭を区画する。門は切妻造本瓦葺の薬医門。塀は桟瓦葺の真壁造黒漆喰仕上で、腰を下見板張とする。総延長三九メートル。街道の歴史的景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014617"},{"id":"00009308","register_sub_id":"101","register_pk":"194101","name":"梅田家住宅表蔵","kana":"うめだけじゅうたくおもてぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市上八町1648","lat":34.62554423,"lng":136.09170334,"geo_status":"db","era":"慶応2年／昭和20年頃改修","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積70㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"24 － 0124","desc":"主屋北側に接し、初瀬街道に面して建つ町家。土蔵造二階建、切妻造桟瓦葺、桁行四間梁間三間、西面に一間半幅の下屋を設ける。妻入で、主屋玄関土間に戸口を開く。基礎は亀甲石積、腰は海鼠壁、上部を漆喰仕上とし、主屋と並び、大型町家の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009308"},{"id":"00009307","register_sub_id":"101","register_pk":"194100","name":"梅田家住宅主屋","kana":"うめだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市上八町1648","lat":34.62549902,"lng":136.091651,"geo_status":"db","era":"慶応2年／大正後期増築・昭和35年改修","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"24 － 0123","desc":"初瀬街道に東面して建つ。木造つし二階建、切妻造桟瓦葺、桁行六間半梁間五間、正面に下屋を設ける。北寄りに間口二間の玄関から通り土間を通し、その南側に田字型に八畳四室の居室を設ける。建ちが低く、下階を出格子、上階を塗り籠めて虫籠窓を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009307"},{"id":"00009309","register_sub_id":"101","register_pk":"194102","name":"梅田家住宅中蔵","kana":"うめだけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市上八町1648","lat":34.62557517,"lng":136.09147254,"geo_status":"db","era":"慶応2年／平成18年改修","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"24 － 0125","desc":"敷地南西奥に建つ。土蔵造二階建、切妻造桟瓦葺、桁行三間梁間二間、東面北寄りに片流れ桟瓦葺の蔵前を付設し、出入口を開ける。小屋組は和小屋とする。外壁は腰を海鼠壁とし、上部は白漆喰仕上げで軒に鉢巻を廻す。中庭に面し、町家の良好な景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009309"},{"id":"00009310","register_sub_id":"101","register_pk":"194103","name":"梅田家住宅渡廊下","kana":"うめだけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県名張市上八町1648","lat":34.62548951,"lng":136.09151299,"geo_status":"db","era":"慶応2年","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"24 － 0126","desc":"主屋と中蔵をつなぐ渡廊下で、南側に便所を附属する。延長一一・一メートル、切妻造桟瓦葺で、主屋寄りで幅をやや広くする。中庭側に丸太柱を配り深い軒を差し出す。東面に片引きのガラス格子戸を嵌めて中庭を眺望でき、落ち着いた空間を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009310"},{"id":"00009022","register_sub_id":"101","register_pk":"162382","name":"岡村家住宅主屋","kana":"おかむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市本町336","lat":34.62055116,"lng":136.08954055,"geo_status":"db","era":"江戸後期／昭和前期・昭和61年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"24－0112","desc":"旧初瀬街道に面して建つ平入町家。木造つし二階建。間口１３ｍ奥行１３ｍと、比較的大きな町家。切妻造桟瓦葺で正面に瓦庇を付け、棟には小さな越屋根を設ける。右手を出入口とし、上屋は大壁で、窓四所を穿つ。近世名張の面影を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009022"},{"id":"00011970","register_sub_id":"101","register_pk":"211108","name":"小川家住宅主屋","kana":"おがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市榊町1404-2","lat":34.622047,"lng":136.088654,"geo_status":"db","era":"江戸末期／昭和30年頃・同50年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"24-241","desc":"初瀬街道沿いの榊町にあり、通りに東面するつし二階建の町家。間口七間半で正面南端二間は出格子を設け、つし二階に格子窓を穿つ。内部は土間に沿って三列に室を並べ、内庭に面する座敷は、出節丸太の床柱を用いた座敷飾りを備える。江戸末期の大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011970"},{"id":"00011972","register_sub_id":"101","register_pk":"211110","name":"小川家住宅西蔵","kana":"おがわけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市榊町1404-2","lat":34.622039,"lng":136.088374,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"24-243","desc":"東蔵の南西方にあり東面する。桁行二間半、梁間二間で敷地に応じて背面は斜めに切る。切妻造、妻入で、掛子塗の観音扉に内網戸片引を建て込み、外壁は腰海鼠壁で飾る。内部は一室で二階正側面に一所ずつ窓を穿つ。醤油醸造業による繁栄を物語る土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011972"},{"id":"00011971","register_sub_id":"101","register_pk":"211109","name":"小川家住宅東蔵","kana":"おがわけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市榊町1404-2","lat":34.622092,"lng":136.088463,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"24-242","desc":"主屋の後方、敷地北側中央にあり南面する。桁行三間、梁間二間、切妻造、平入とする。掛子塗の観音扉に内板戸、網戸片引を建て込み、外壁は腰海鼠壁で装飾する。内部は一室で、二階妻面に一所ずつ窓を穿つ。中庭からの良好な景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011971"},{"id":"00011517","register_sub_id":"101","register_pk":"210383","name":"貝増家住宅主屋","kana":"かいますけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市柳原町3339","lat":34.61953194,"lng":136.091124,"geo_status":"db","era":"明治初期／昭和38年増築、平成21年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"24-0240","desc":"通りに北面するつし二階建の町家。一階正面は繊細な格子をたてて弁柄を塗り、つし部分は横細の窓を穿ち、軒先まで塗込める。内部は西寄りの土間に越屋根をあげ、東に四室を田字形に並べ、庭を望む南東室に座敷飾を備える。市街地の歴史的景観を構成する住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011517"},{"id":"00011329","register_sub_id":"101","register_pk":"209166","name":"木村家住宅石積塀","kana":"きむらけじゅうたくいしづみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県度会郡度会町駒ヶ野字里ヲキの南651・661合併","lat":34.379673,"lng":136.595647,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、総延長44m","structure_material":"石造","registered":"2016.11.29(平成28.11.29)","register_no":"24 － 0238","desc":"敷地の西辺と北辺を画す石積の塀。敷地西辺北端に建つ長屋門に接続して、東に二一メートル、南に折れ曲がり二三メートルを測る。周辺で採取される自然石を高さ約一・三から一・七メートルに野面積とする。上部に槇垣を設けて、屋敷構えに整った印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011329"},{"id":"00011328","register_sub_id":"101","register_pk":"209165","name":"木村家住宅蔵","kana":"きむらけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県度会郡度会町駒ヶ野字里ヲキの南651・661合併","lat":34.379705,"lng":136.595985,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"24 － 0237","desc":"敷地北東隅に西面して建つ。土蔵造二階建で、平入とし、正面には壁で囲んだ蔵前を設ける。小屋は登梁で、屋根は置屋根形式として桟瓦を葺く。鉢巻部分に白漆喰塗を見せるほかは簓子下見板張として、山あいの農村風景の中にあって、落ち着いた外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011328"},{"id":"00011327","register_sub_id":"101","register_pk":"209164","name":"木村家住宅主屋","kana":"きむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県度会郡度会町駒ヶ野字里ヲキの南651・661合併","lat":34.379659,"lng":136.595848,"geo_status":"db","era":"江戸末期／明治15頃増築、昭和40頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積133㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"24 － 0236","desc":"敷地北寄りに西面して建つ元紀州藩士宅。幕末に藩主の脱出経路として駒ヶ野が選ばれ、宿所とできるよう建て替えられたとの伝承があり、床上部が上段と下段に分かれ、駕籠寄せが設けられる。桟瓦葺であるが、屋根中央に二筋の丸瓦を葺く地域性も見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011327"},{"id":"00008293","register_sub_id":"101","register_pk":"133935","name":"旧伊藤伝七別邸玄関棟","kana":"きゅういとうでんしちべっていげんかんとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市高砂町3492-67他","lat":34.96156127,"lng":136.63627448,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積152㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0090","desc":"東洋紡績を創業した伊藤伝七の別邸を利用して明治３９年に開業した料亭。 『三重県近代和風建築総合調査報告書』（三重県教育委員会、２００８）。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008293"},{"id":"00012163","register_sub_id":"101","register_pk":"352962","name":"旧猪子家住宅主屋","kana":"きゅういのこけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県志摩市阿児町神明前方693-8","lat":34.312417,"lng":136.827491,"geo_status":"db","era":"昭和9年／昭和中期、平成29年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"24-245","desc":"英虞湾を見下ろす敷地に南面する。木造平屋建で、玄関と台所部を張り出し、各々入母屋造の屋根を架け変化に富む外観。和室は座敷飾りを備え、欄間に松と鶴の彫刻を施し、玄関脇の洋間は旧書斎で、ガラス戸をたて格天井を張り、和洋の上質な意匠を併せ持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012163"},{"id":"00012164","register_sub_id":"101","register_pk":"352963","name":"旧猪子家住宅土蔵","kana":"きゅういのこけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県志摩市阿児町神明前方693-8","lat":34.312455,"lng":136.827347,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"24-246","desc":"主屋の西に東面して建つ。桁行五・四メートル、梁間三・六メートルの土蔵造二階建で寄棟造の屋根を架ける。内部は一室で、小屋組は和小屋。外壁は、軒下まで簓子下見板張とし、戸口は両開板扉を吊る。主屋と共に敷地の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012164"},{"id":"00012165","register_sub_id":"101","register_pk":"352964","name":"旧猪子家住宅門柱","kana":"きゅういのこけじゅうたくもんちゅう","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県志摩市阿児町神明前方693-8","lat":34.312261,"lng":136.827083,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造、間口3.0m、南北脇柱付","structure_material":"石造","registered":"2018.03.27(平成30.03.27)","register_no":"24-247","desc":"敷地西面に建つ石造の門柱。間口三・〇メートルで主柱を立て、両端に敷地に合わせて脇柱を立てる。主柱は、方四〇センチメートルで、上部に笠石を載せ、側面を瘤出し仕上げとし立体感を出す。屋敷地を画し、重厚な表構えで街路の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012165"},{"id":"00014618","register_sub_id":"101","register_pk":"515160","name":"旧加藤家住宅主屋","kana":"きゅうかとうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県度会郡南伊勢町神前浦135-1","lat":34.275625,"lng":136.50074167,"geo_status":"db","era":"明治前期／昭和50年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"24 - 0326","desc":"神前浦の集落海寄りに建つ旧家の主屋。切妻造平入本瓦葺、つし二階建で北と東に下屋を付し、小屋組は和小屋と登梁を併用する。平面は東の表側を土間玄関、裏側床上とし、西は田の字型平面で続き間座敷を設ける。志摩地方の典型的な間取りの貴重な漁村民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014618"},{"id":"00014619","register_sub_id":"101","register_pk":"515161","name":"旧加藤家住宅土蔵","kana":"きゅうかとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県度会郡南伊勢町神前浦135-1","lat":34.2757,"lng":136.50067222,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"24 - 0327","desc":"旧家の主屋の北西に位置する家財蔵。土蔵造二階建、切妻造平入本瓦葺で、外壁は元は漆喰仕上杉皮張、鉢巻に漆喰塗を現す。南面の蔵前で主屋と接続する内蔵形式で各階板敷、戸口は鳥居枠を構えて掛子塗扉を吊り、窓は二階西面に一つ。敷地北面外郭を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014619"},{"id":"00014248","register_sub_id":"101","register_pk":"509638","name":"旧小渕医院住居棟","kana":"きゅうこぶちいいんじゅうきょとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県津市一志町波瀬1969","lat":34.62717778,"lng":136.39226111,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0315","desc":"診療棟の西に南北棟で接続し、南端を東西棟としたＴ字棟を持つ。二階建入母屋造桟瓦葺で、診療棟の中廊下から矩折で東縁に続き、縁に面して二列五室を配する。二階も東縁を通し数寄屋風の続き間座敷を配す。建ちが高く縁にガラス戸を建てる瀟洒な近代和風。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014248"},{"id":"00010815","register_sub_id":"101","register_pk":"201650","name":"旧杉本家住宅主屋","kana":"きゅうすぎもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県津市白山町八対野1000","lat":34.649629,"lng":136.328219,"geo_status":"db","era":"明治前期／明治30年代移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0216","desc":"津市西部の農山村部に所在し、敷地中央に南面して建つ。右土間とし、床上部は食違い六間取を基本に、西端列にキャクマ、仏間、ネマの三室を並べ、特にキャクマと仏間は、座敷飾や建具なども整った意匠をもつ。当地の明治期における大型民家の好例となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010815"},{"id":"00010817","register_sub_id":"101","register_pk":"201652","name":"旧杉本家住宅長屋","kana":"きゅうすぎもとけじゅうたくながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県津市白山町八対野1000","lat":34.649578,"lng":136.328406,"geo_status":"db","era":"明治38頃／昭和30頃移築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0218","desc":"主屋の東に接続し、敷地東辺沿いに南方へ延びる桁行一九メートルの長屋で、当初は蚕室に使われた。内部を四室に区切り、西正面に半間幅の土間廊下を通す。室内は南端間を土間とするほかは板床で、内部を二階建とする。良好な屋敷構えを形成する付属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010817"},{"id":"00010818","register_sub_id":"101","register_pk":"201653","name":"旧杉本家住宅長屋門","kana":"きゅうすぎもとけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県津市白山町八対野1000","lat":34.649519,"lng":136.32843,"geo_status":"db","era":"明治前期／明治12頃移築・平成23改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0219","desc":"敷地南辺東寄りに建つ。西寄りに間口二・三メートルの門を開き、東寄りを平屋建で床板張の長屋とする。正面外壁は竪板張、側面は簓子下見板張とする。明治期になり、近隣から長屋門を移築して屋敷構えを整えたもので、近代における屋敷構えの変容を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010818"},{"id":"00010816","register_sub_id":"101","register_pk":"201651","name":"旧杉本家住宅離れ座敷","kana":"きゅうすぎもとけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県津市白山町八対野1000","lat":34.649477,"lng":136.328177,"geo_status":"db","era":"明治26頃／昭和10改修","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0217","desc":"主屋から渡廊下を介して西に接続し、東面して建つ。南から八畳、六畳、四畳半茶室と三畳の水屋を並べ、各室に大小の座敷飾を備える。東側は主庭に面する半間幅の廊下を通して開放的な構成とし、茶室から北庭への眺望にも配慮する、雅趣ある接客用の離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010816"},{"id":"00016672","register_sub_id":"101","register_pk":"579156","name":"旧高北家住宅主屋","kana":"きゅうたかきたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市上八町1323","lat":34.625598,"lng":136.089749,"geo_status":"db","era":"昭和36年頃／昭和56年移築、平成29年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"24 - 0342","desc":"市街地中心部に位置する農耕具製造販売業の創業家の旧宅。南面して建つ平屋建入母屋造桟瓦葺の東西棟で、東寄りに入母屋造玄関を付す。内部は西に2室の座敷を配し、それぞれ床を構える。座敷境の欄間には馬と犂をモチーフとした彫刻を飾り、生業を称える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016672"},{"id":"00010821","register_sub_id":"101","register_pk":"201656","name":"旧平田家住宅米蔵","kana":"きゅうひらたけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市千代田町941","lat":35.03323,"lng":136.622104,"geo_status":"db","era":"明治20頃／大正3改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積96㎡","structure_material":"土蔵造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0222","desc":"敷地南東角に建つ。土蔵造で鉢巻を廻らし、屋根は切妻造桟瓦葺で西面と南面に下屋を付す。内部は南北に二分し、小屋は登梁形式をトラス組で補強する。内部は板床で、壁に荷摺木を斜めに並べて打付けるという特異な仕様を見せる。敷地南の景観を整える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010821"},{"id":"00010819","register_sub_id":"101","register_pk":"201654","name":"旧平田家住宅主屋","kana":"きゅうひらたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市千代田町941","lat":35.033447,"lng":136.622015,"geo_status":"db","era":"明治3頃／大正10頃改修","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積229㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0220","desc":"田園地帯の敷地中央に南面して建つ。桁行一〇間梁間五間半の規模を持ち、大型で切妻造桟瓦葺屋根の周囲に下屋を廻らし、正面に入母屋造の式台を構える。平面は東側を土間とし、西側は六間取で表列に座敷を並べる。旧家らしい雄大な佇まいを見せる大型の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010819"},{"id":"00010820","register_sub_id":"101","register_pk":"201655","name":"旧平田家住宅書院","kana":"きゅうひらたけじゅうたくしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市千代田町941","lat":35.033539,"lng":136.621872,"geo_status":"db","era":"明治17頃","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0221","desc":"主屋の西に接続して建つ。屋根は入母屋造桟瓦葺で周囲に下屋を廻らす。平面は一五畳書院と十畳次の間を並べ縁を廻らし、東に仏間と四畳半を配す。随所に屋久杉や春日杉などの良材を用い、部屋境に山月などを透彫りした板欄間を嵌める、端正な意匠の書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010820"},{"id":"00010825","register_sub_id":"101","register_pk":"201660","name":"旧平田家住宅中門及び塀","kana":"きゅうひらたけじゅうたくちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市千代田町941","lat":35.033367,"lng":136.621889,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"中門 木造、瓦葺、間口1.8m 塀 木造、瓦葺、総延長13m","structure_material":"中門 木造","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0226","desc":"主屋の式台脇から南の女中部屋に伸びる。中門はほぼ中央に位置する薬医門で、屋根は切妻造桟瓦葺とする。塀は総延長一三メートルで、屋根は同様に切妻造桟瓦葺とし、壁は真壁漆喰塗、表側は腰を簓子下見板張とする。主庭と前庭を区画し、庭空間に格式を醸す門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010825"},{"id":"00010823","register_sub_id":"101","register_pk":"201658","name":"旧平田家住宅西蔵","kana":"きゅうひらたけじゅうたくにしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県四日市市千代田町941","lat":35.03362,"lng":136.622027,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積69㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0224","desc":"主屋の北西寄りに位置し、家財道具を収める土蔵。土蔵造二階建で、桁行八間半梁間三間半の長大な土蔵で、屋根は切妻造桟瓦葺である。東蔵同様、花崗岩亀甲積の基礎に建ち、主屋側の腰壁を海鼠壁とする。内部は板壁や二階天井板表面に鉄製の桟を打付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010823"},{"id":"00010822","register_sub_id":"101","register_pk":"201657","name":"旧平田家住宅東蔵","kana":"きゅうひらたけじゅうたくひがしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県四日市市千代田町941","lat":35.033542,"lng":136.622119,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0223","desc":"主屋の北側に位置する、家財道具を納める土蔵。桁行二間半、梁間二間、土蔵造二階建で東西棟の屋根を切妻造桟瓦葺とし、南面の出入口に庇を付す。内部一階は板壁、二階は漆喰壁である。花崗岩亀甲積の基礎に建ち、西蔵とともに敷地北面の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010822"},{"id":"00010824","register_sub_id":"101","register_pk":"201659","name":"旧平田家住宅門柱","kana":"きゅうひらたけじゅうたくもんちゅう","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県四日市市千代田町941","lat":35.03326,"lng":136.621947,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"石造、間口4.2m、左右脇門及び塀付","structure_material":"石造","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0225","desc":"敷地南に建つ花崗岩製の門柱。間口三・二メートル、左右脇門付で本柱二本と脇柱二本からなり、本柱は高さ四・〇メートル、脇柱は高二・八メートルで、いずれも基礎と柱身、柱頭よりなり、柱頭はコーニス下に雷文を刻む。旧家の表構えに相応しい豪壮な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010824"},{"id":"00005279","register_sub_id":"101","register_pk":"106267","name":"旧広野家住宅（角屋）内蔵","kana":"きゅうひろのけじゅうたく（かどや）うちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県鳥羽市鳥羽4-1244-2","lat":34.47605662,"lng":136.84449628,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"24 － 0059","desc":"敷地の南西，主屋の背面に建つ。桁行９ｍ，梁間４ｍの規模で，東西棟，切妻造，本瓦葺の土蔵造２階建。基礎は花崗岩の石積とし，床高を高くとる。平入で，北側壁面に入口を設ける。外壁は簓子下見板張（現鉄板張）。西方からの屋敷景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005279"},{"id":"00005278","register_sub_id":"101","register_pk":"106266","name":"旧広野家住宅（角屋）主屋","kana":"きゅうひろのけじゅうたく（かどや）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県鳥羽市鳥羽4-1244-2","lat":34.47621193,"lng":136.84445821,"geo_status":"db","era":"文政8","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"木造平屋及び2階建、瓦葺、建築面積220㎡","structure_material":"木造平屋及び2階建","registered":"2006.03.02(平成18.03.02)","register_no":"24 － 0058","desc":"北辺及び西辺を接道する敷地の北西隅に北面して建つ。屋根は切妻造，桟瓦葺とし，東西棟の木造つし２階建の西に木造２階建が接して並び，その背面に南北棟の木造平屋建が接続する。外壁は簓子下見板張とする。江戸期の大庄屋の主屋の様子を伝え貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005278"},{"id":"00005280","register_sub_id":"101","register_pk":"106268","name":"旧広野家住宅（角屋）土蔵","kana":"きゅうひろのけじゅうたく（かどや）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県鳥羽市鳥羽4-1244-2","lat":34.47602896,"lng":136.844604,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"24 － 0060","desc":"内蔵の東に建つ。桁行５ｍ，梁間３ｍの規模で，南北棟，切妻造，本瓦葺の土蔵造２階建である。基礎は花崗岩の石積とし，床高を高くとる。妻入とし，北側壁面に出入口を設ける。外壁は簓子下見板張とする。歴史的な屋敷構を構成する要素として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005280"},{"id":"00007507","register_sub_id":"101","register_pk":"108489","name":"旧細川家住宅川蔵","kana":"きゅうほそかわけじゅうたくかわぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市新町136","lat":34.61834923,"lng":136.086326,"geo_status":"db","era":"明治前期／平成20改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鉄板葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"24 － 0076","desc":"敷地の南奥に北面して建つ。桁行４．９ｍ梁間４．４ｍ、土蔵造２階建、切妻造妻入鉄板葺。正面東寄りを出入口とし、掛子塗の両開戸を吊り、その両脇を海鼠壁とする。２階の正背妻面には庇付の窓を開ける。敷地後背を流れる名張川沿いの河岸景観に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007507"},{"id":"00007505","register_sub_id":"101","register_pk":"108487","name":"旧細川家住宅主屋","kana":"きゅうほそかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市新町136","lat":34.61859652,"lng":136.08635693,"geo_status":"db","era":"明治前期／平成20改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造二階建、瓦葺、建築面積119㎡","structure_material":"木造二階建","registered":"2009.01.08(平成21.01.08)","register_no":"24 － 0074","desc":"初瀬街道沿いに北面して建つ。間口９．７ｍ奥行１３ｍ、木造２階建、切妻造桟瓦葺。１階正面は意匠の異なる格子で構成し、２階は塗籠で虫籠窓を設け、両袖に卯建を付ける。内部は通り土間沿いに３室を並べる。もと宿場町の風情を伝える平入町家建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007505"},{"id":"00007506","register_sub_id":"101","register_pk":"108488","name":"旧細川家住宅中蔵","kana":"きゅうほそかわけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市新町136","lat":34.61845141,"lng":136.08639976,"geo_status":"db","era":"明治前期／平成20改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"24 － 0075","desc":"主屋の南後方、中庭を挟んで北面して建つ。桁行５．９ｍ梁間３．９ｍ、土蔵造平屋建、切妻造桟瓦葺。腰は海鼠壁で、正面西寄りを出入口とし、両開戸を吊り、庇を掛ける。窓を上下階でずらして配置し、軒を置屋根風形式に塗り込めるなど特徴的な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007506"},{"id":"00007508","register_sub_id":"101","register_pk":"108490","name":"旧細川家住宅門","kana":"きゅうほそかわけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市新町136","lat":34.618629,"lng":136.08640452,"geo_status":"db","era":"明治前期／平成20改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"24 － 0077","desc":"主屋東側に接して建つ。間口３．２ｍの塀の中央に、門口１．３ｍの門を開き、格子戸をたてる。塀は切妻造桟瓦葺で、門口には板葺の小庇を付け、屋根を二段に重ねる。小庇の桁を絵様付の持送りで受ける上質なつくりで、旧家の格式を伝える門構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007508"},{"id":"00016398","register_sub_id":"101","register_pk":"536465","name":"旧向井家住宅石塀","kana":"きゅうむかいけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県志摩市阿児町甲賀字広646他","lat":34.32129444,"lng":136.87630833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、延長173m、木戸門付","structure_material":"石造","registered":"2025.11.17(令和7.11.17)","register_no":"24 - 0341","desc":"正門の東西に延び、敷地周囲を画す総延長１７３メートルの石塀。北側は石塀と一体的に祠を築き、石碑を祀る。花崗岩を用いた切込接の布積、谷積を組合せ、隅を算木積で精緻に積上げるなど、石工の高い技術を示す。重厚な屋敷構えで、独特な景観をつくる石塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016398"},{"id":"00016396","register_sub_id":"101","register_pk":"536463","name":"旧向井家住宅衣装蔵","kana":"きゅうむかいけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県志摩市阿児町甲賀字広646他","lat":34.32164722,"lng":136.87619167,"geo_status":"db","era":"明治42年／昭和中期改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"24 - 0339","desc":"主屋の北東に位置し、道具蔵の西隣に建つ衣装蔵。土蔵造二階建、切妻造妻入桟瓦葺の東西棟で西面に戸口を設け、庇を付す。内部は各階一室で床を拭板張とし、小屋組は妻梁に架かる地棟に束を立て棟木を受ける。道具蔵や石塀と一体で敷地景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016396"},{"id":"00016394","register_sub_id":"101","register_pk":"536461","name":"旧向井家住宅主屋","kana":"きゅうむかいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県志摩市阿児町甲賀字広646他","lat":34.321525,"lng":136.87610556,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積194㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"24 - 0337","desc":"阿児川南岸の丘陵地に位置する旧家の主屋。敷地北側に南面して建つ、平屋建切妻造平入桟瓦葺で周囲に下屋を廻らす。南面中央西寄りに式台を構え、内部の東は大広間で成の高い差鴨居を廻らし、西は2列４室を配す。妻面に鎧板を付し、当地域らしい外観の民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016394"},{"id":"00016397","register_sub_id":"101","register_pk":"536464","name":"旧向井家住宅正門","kana":"きゅうむかいけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県志摩市阿児町甲賀字広647","lat":34.32140833,"lng":136.87633611,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造、瓦葺、間口1.9m、袖塀付","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"24 - 0340","desc":"敷地東面の階段上部に建つ、切妻造平入桟瓦葺の門。冠木上に架けた三筋の梁上に立つ束で棟木を受け、軒は一軒疎棰。中央の門口にケヤキ一枚板の重厚な門扉を開く。脇間の壁は黒漆喰塗で、腰は竪板張とする。石塀と一体で旧家の格式ある表構えをつくる正門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016397"},{"id":"00016395","register_sub_id":"101","register_pk":"536462","name":"旧向井家住宅道具蔵","kana":"きゅうむかいけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県志摩市阿児町甲賀字広646他","lat":34.32166389,"lng":136.87624167,"geo_status":"db","era":"明治36年／昭和中期改修","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"24 - 0338","desc":"敷地北東隅の石垣上に建つ、什器などの収納蔵。土蔵造二階建、切妻造平入桟瓦葺南北棟で、西面に下屋を付し、蔵前とする。各階内部は窓が少なく、閉鎖的な一室で、床は拭板張とする。小屋は登梁形式。主屋や衣装蔵、石塀と一体で、敷地景観を形成する道具蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016395"},{"id":"00011516","register_sub_id":"101","register_pk":"210467","name":"見庵（旧小泉家住宅主屋）","kana":"けんあん（きゅうこいずみけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県松阪市魚町1643他","lat":34.57857889,"lng":136.52883806,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"24-0239","desc":"松坂城下の町人地で魚町通りに東面して建つ、つし二階建の町家で、正面に出格子をたてて庇を付ける。内部は南側に土間を通し、床上部は二列構成で居室を食い違いに配する。建物前面の幕板や緩勾配の屋根、平面構成に、松坂城下の中規模町家の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011516"},{"id":"00009019","register_sub_id":"101","register_pk":"162379","name":"佐佐木信綱生家主屋","kana":"ささきのぶつなせいかしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県鈴鹿市石薬師町字中町1707-3","lat":34.90351657,"lng":136.54762341,"geo_status":"db","era":"明治元年／明治中期・昭和45年移築・平成20年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0109","desc":"旧東海道沿いの敷地に東面して建つ。切妻造桟瓦葺で、正・背面に瓦庇を付ける。間口１２ｍ奥行１０ｍのつし二階建。南端に通り土間を設け、床上は二列各三室とする。北列最奥が主座敷でトコやトコ脇を構える。旧石薬師宿に残る数少ない町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009019"},{"id":"00009020","register_sub_id":"101","register_pk":"162380","name":"佐佐木信綱生家土蔵","kana":"ささきのぶつなせいかどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県鈴鹿市石薬師町字中町1707-3","lat":34.90357445,"lng":136.54761172,"geo_status":"db","era":"明治8年／昭和7年移築","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積14㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0110","desc":"主屋北面の西寄りに建つ。桁行４．６ｍ梁間３．１ｍ、土蔵造二階建。切妻造桟瓦葺とし、南面に庇を付設し、出入口を穿つ。外壁は腰板張の漆喰仕上げ。内部は半間ごとに柱をたて、貫で固め、壁板張とする。主屋とともに宿場町家の趣を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009020"},{"id":"00009976","register_sub_id":"101","register_pk":"196123","name":"下津家住宅珂雪園","kana":"しもずけじゅうたくかせつえん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県津市一身田町字寺町749","lat":34.76062999,"lng":136.50417121,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0166","desc":"当主の接客用に建てられた離れで、主棟は三畳の上段のトコを持つ一五畳半と一〇畳からなり、縁の軒は深く軽やかに差出し、座敷飾の意匠も洗練されている。主棟の西側に四畳茶室延庵を配し、北側の渡廊下を介して待合を兼ねた玄関を構える。風雅な趣の離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009976"},{"id":"00009977","register_sub_id":"101","register_pk":"196124","name":"下津家住宅外待合","kana":"しもずけじゅうたくそとまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県津市一身田町字寺町749","lat":34.76050799,"lng":136.50425718,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積8.0㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0167","desc":"珂雪園の主座敷南東側に庭を挟んで建つ。木造平屋建、招造銅板葺である。北半の主体部は壁付の腰掛と独立した腰掛を備える特異な形式で、前面に頂部半円の窓を開ける。南半には落棟の雪隠が続く。軸部は丸太を主材として数寄屋風にまとめ、風情ある趣を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009977"},{"id":"00009978","register_sub_id":"101","register_pk":"196125","name":"下津家住宅長屋門","kana":"しもずけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県津市一身田町字寺町749","lat":34.76081564,"lng":136.50423329,"geo_status":"db","era":"江戸末期／平成21改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0168","desc":"専修寺門前の通りに北面して建つ長屋門で、入母屋造桟瓦葺である。西寄りの門口に板扉を吊り、西脇に潜りを開く。腰を簓子下見板張として、門口両脇の物見格子の他、与力窓や無双窓などを配した風格ある外観をもち、寺内町の寺侍の屋敷構えを良好に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009978"},{"id":"00009774","register_sub_id":"101","register_pk":"195603","name":"鈴木家住宅蔵","kana":"すずきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市六呂木町852","lat":34.50261908,"lng":136.45009256,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0159","desc":"主屋南側の石垣上に東西棟で建ち、北面を戸口として下屋を設ける。外壁には黒色塗装を施した簓子下見板を高く張り、南面の上下階に小窓を穿つ。土蔵造二階建で、一階に米と味噌、二階に家財道具を納めた。建ちの高い土蔵で、屋敷の正面構えを引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009774"},{"id":"00009773","register_sub_id":"101","register_pk":"195602","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市六呂木町852","lat":34.50273448,"lng":136.45004973,"geo_status":"db","era":"明治中期／昭和45・平成14改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積156㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0158","desc":"和歌山街道西側の傾斜地に位置する。石垣を築いて造成した敷地北寄りに南面して建ち、切妻造桟瓦葺である。四間取系平面をもつ民家で、鍵座敷型に室を配する。広い小屋裏ではかつて養蚕も行った。明治期における当地域の民家建築の様相を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009773"},{"id":"00014253","register_sub_id":"101","register_pk":"509643","name":"住川家住宅主屋","kana":"すみかわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市新田443","lat":34.66075556,"lng":136.14130556,"geo_status":"db","era":"明治中期／大正後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、茅葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0320","desc":"初瀬街道に東面する新田宿の農家。平屋建入母屋造茅葺で四周に瓦葺の下屋を廻す。南を土間、北を二列五室の床上部として東西面に縁を通す。北東に床付の座敷を設ける。差物に三本溝を切るなど古式も残す。風情のある茅葺農家が街道沿いの宿場町の景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014253"},{"id":"00014616","register_sub_id":"101","register_pk":"515158","name":"澄野家住宅主屋","kana":"すみのけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県多気郡明和町大字斎宮字牛葉118","lat":34.53638333,"lng":136.61496389,"geo_status":"db","era":"大正5年／昭和40年頃・令和元年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積107㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"24 - 0324","desc":"伊勢街道に北面して建つ町家。つし二階建切妻造平入桟瓦葺で正背面に下屋を下し、正面は格子を構え、軒先に霧除を付す。内部は東を通り土間、西を整形四間取とする。西端に床構え、仏壇、押入を配す。良材を用いた上質な町家で、街道の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014616"},{"id":"00002774","register_sub_id":"101","register_pk":"103764","name":"田垣内家住宅石蔵","kana":"たがいとけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県熊野市五郷町桃崎345","lat":33.984901,"lng":136.041138,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造2階建、瓦葺、建築面積29㎡","structure_material":"石造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"24 － 0045","desc":"宅地北西隅に東面して建つ。近郷から産出される花崗岩による石造２階建の道具蔵で，寄棟造，桟瓦葺，１辺約５ｍのほぼ正方形平面をもつ。小規模ながら胴蛇腹，軒蛇腹を廻し，出入口には切妻のポーチを付けるなど凝った外観で，集落の中でも目立つ存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002774"},{"id":"00013260","register_sub_id":"101","register_pk":"366249","name":"伊達家住宅主屋","kana":"だてけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県鈴鹿市江島本町3326","lat":34.83319444,"lng":136.59379722,"geo_status":"db","era":"明治中期／明治後期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部平屋建、瓦葺、建築面積262㎡","structure_material":"木造2階一部平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"24 － 0275","desc":"市東部の伊勢湾沿岸に位置し、伊勢街道に西面する商家建築。木造二階建、切妻造桟瓦葺で、中央主体部の南側に米蔵、北側に納戸が並ぶ。主体部南端に通り土間、北に座敷を二列並べる。黒漆喰の外壁に虫籠窓を穿つなど、重厚な表構えの豪商の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013260"},{"id":"00012575","register_sub_id":"101","register_pk":"367870","name":"田中家住宅石垣","kana":"たなかけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯高町波瀬字町212","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、延長26m","structure_material":"石造","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0262","desc":"表納屋東端から前座敷南端にかけての敷地東南部を造成する石垣で、櫛田川に面した崖地に矩折れに築かれる。高さ8・1メートルの規模で河原石を谷積にして、城郭を思わせる壮大な景観をかたちづくる。川に迫り出した独特な屋敷構えを象徴する構造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012575"},{"id":"00012571","register_sub_id":"101","register_pk":"367866","name":"田中家住宅表土塀","kana":"たなかけじゅうたくおもてどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯高町波瀬字町213","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土塀、瓦葺、延長15m","structure_material":"土塀","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0258","desc":"主屋東側面の敷地境を区切る塀で、主屋東面から敷地東南隅を矩折れに延びて東蔵南面に取付く。人頭大の河原石を加工して谷積とした石積基礎の上に漆喰塗の土塀を築き、桟瓦葺の屋根をかける。主屋、東蔵と一体となって街道沿いの歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012571"},{"id":"00012569","register_sub_id":"101","register_pk":"367864","name":"田中家住宅表納屋","kana":"たなかけじゅうたくおもてなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯高町波瀬212","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"明治33年","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積63㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0256","desc":"街道を挟んで主屋と対面し、北面して建つ。切妻造桟瓦葺の二階建で、北面の東西に戸口を開き、北西二面に下屋を廻す。内部は東西両端を土間、中央を板敷とし、西土間には二階に上るための吹抜けを設ける。主屋と同じく街道の歴史的景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012569"},{"id":"00012565","register_sub_id":"101","register_pk":"367860","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯高町波瀬字町213","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"明治29年／大正期・昭和前期増築、昭和30年頃改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、瓦葺、建築面積356㎡、塀付","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0252","desc":"旧和歌山街道波瀬宿の脇本陣を務めた旧家で、主屋は街道に南面して建つ。切妻造桟瓦葺の二階建、正面は出桁造で下屋に霧除けを付し、一階に格子、二階に虫籠窓と出格子を並べる。良材を用いた大型町家で、当宿場最大規模の商家に相応しい堂々たる構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012565"},{"id":"00008292","register_sub_id":"101","register_pk":"133934","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県津市美杉町三多気162","lat":34.52011451,"lng":136.22032507,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0089","desc":"南向き斜面の敷地中央に南面して建ち、桁行１３ｍ梁間８．３ｍ、木造平屋建、入母屋造茅葺である。西側の床上部は、表側を座敷とする伊賀地方南部からその周辺に分布した前座敷型三間取を基本としている。周囲の著名な桜とともに豊かな山村景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008292"},{"id":"00012567","register_sub_id":"101","register_pk":"367862","name":"田中家住宅新蔵","kana":"たなかけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県松阪市飯高町波瀬字町213","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"大正元年／昭和30年頃増築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階及び木造平屋建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階及び木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0254","desc":"敷地の奧、主屋の北西に建つ家財蔵。土蔵造二階建、東西棟の切妻造で、南を正面として蔵前座敷を附属する。外壁は漆喰塗、腰壁は南面を海鼠壁、他三面を下見板張とする。平屋建の蔵前座敷は上質な数寄屋風で仕上げる。上層商家の伝統的な屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012567"},{"id":"00012573","register_sub_id":"101","register_pk":"367868","name":"田中家住宅西土塀","kana":"たなかけじゅうたくにしどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯高町波瀬字町213","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土塀、瓦葺、延長27m","structure_material":"土塀","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0260","desc":"主屋西側の敷地境を区切る塀。東土塀と同じく河原石を谷積とする石積基礎の上に漆喰塗の土塀を築き、桟瓦葺の屋根を載せる構成だが、街道に面する南端は末広がりの切石積とし、鬼瓦を戴くなど重厚に仕上げる。主屋と並び建って上層商家の表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012573"},{"id":"00012570","register_sub_id":"101","register_pk":"367865","name":"田中家住宅西納屋","kana":"たなかけじゅうたくにしなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県松阪市飯高町波瀬212","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"大正期／平成2年改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0257","desc":"表納屋の西側に東面して建つ。切妻造桟瓦葺の二階建で、正面の北寄りに戸口、南半に出格子付窓を設け、下屋を通す。外壁は真壁の漆喰塗で、二階正面には虫籠窓を設け、側背面を下見板張とする。街道沿いにあって歴史的景観を構成する要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012570"},{"id":"00012566","register_sub_id":"101","register_pk":"367861","name":"田中家住宅東蔵","kana":"たなかけじゅうたくひがしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯高町波瀬字町213","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"明治38年","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0253","desc":"主屋の東に建つ道具蔵。土蔵造二階建、東西棟の切妻造で、西と北に戸口を開いて下屋を廻す。街道側の南面は石積基礎、腰壁縦板張の漆喰塗とし、上下階に庇付の両開窓を設け、階境には水切を通すなど丁寧につくる。街道沿いの歴史的景観を構成する要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012566"},{"id":"00012572","register_sub_id":"101","register_pk":"367867","name":"田中家住宅東土塀","kana":"たなかけじゅうたくひがしどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯高町波瀬字町213","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"明治38年","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土塀、瓦葺、延長24m","structure_material":"土塀","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0259","desc":"東蔵背面の敷地境を区切る塀で、東蔵北面から敷地東北隅を矩折れに延びる。河原石を谷積とする石積基礎の上に漆喰塗の土塀を築き、桟瓦葺の屋根を載せる構成で、地形にあわせて北半部の基礎を石垣状に高くつくる。主屋の北東にある庭園の添景となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012572"},{"id":"00012568","register_sub_id":"101","register_pk":"367863","name":"田中家住宅前座敷（洗耳亭）","kana":"たなかけじゅうたくまえざしき（せんじてい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市飯高町波瀬212","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"明治16年／明治40年頃増築","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0255","desc":"櫛田川に面した敷地南側に建ち、一部を石垣から張出す。切妻造の西棟と入母屋造の東棟からなる上質な数寄屋座敷で、川側を開放的につくり、渓流の眺望を借景に取り込む。高い石垣上に雁行する外観が、自然景観と融合した印象的な屋敷構えを演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012568"},{"id":"00012574","register_sub_id":"101","register_pk":"367869","name":"田中家住宅南土塀","kana":"たなかけじゅうたくみなみどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯高町波瀬字町210-1、212","lat":34.423126,"lng":136.146118,"geo_status":"geocoded","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土塀、瓦葺、延長27m","structure_material":"土塀","registered":"2018.11.02(平成30.11.02)","register_no":"24 － 0261","desc":"西納屋西側の敷地境を区切る塀。河原石を谷積とする石積基礎は他の土塀と共通だが、上部は古瓦の埋込み仕上の土塀とし、中段には丸瓦の輪違や軒唐草を用いてアクセントをつける。屋根は桟瓦葺。敷地裏手にありながらも丁寧なつくりで全体の屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012574"},{"id":"00005277","register_sub_id":"101","register_pk":"106265","name":"千歳文庫","kana":"ちとせぶんこ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県津市大字垂水字千歳3032-21","lat":34.69824394,"lng":136.50527666,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造4階建、銅板葺、建築面積157㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2006.03.02(平成18.03.02)","register_no":"24 － 0057","desc":"ＲＣ造４階建で，屋根は鉄骨トラスを組み，銅板瓦棒葺とする。平面は南北に長く，南端を半円形とし，西に階段室が取付く。外壁は煉瓦タイル張とし，各階同位置に窓を配し，３階，４階には南面にバルコニーを設ける。装飾を抑制し，堅牢な外観を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005277"},{"id":"00002630","register_sub_id":"101","register_pk":"103620","name":"寺村家住宅主屋","kana":"てらむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊賀市上野福居町3337-1","lat":34.764774,"lng":136.126129,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"24 － 0042","desc":"もと両替商森川六右衛門の居宅で，旧上野城下に残る最古と考えられる町家。角地に建ち西を正面とした入母屋造，桟瓦葺，妻入で，表側を全面店舗とし，その裏に居室を配する。間仕切や内部造作の改造は大きいが，軸部や軒の低い外観は古い姿を良く残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002630"},{"id":"00002631","register_sub_id":"101","register_pk":"103621","name":"寺村家住宅前蔵","kana":"てらむらけじゅうたくまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊賀市上野福居町3337-1","lat":34.764717,"lng":136.126083,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"24 － 0043","desc":"主屋の南に棟を表通りに平行に配して建つ。２階建，漆喰塗の土蔵で，切妻造の主体部の前後及び主屋側北面に一段下げて下屋を付属する。通り側外壁腰部分のなまこ壁は「鼓繋ぎ」と呼ばれる独特のモチーフになり，妻入の主屋と並んで独特の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002631"},{"id":"00013821","register_sub_id":"101","register_pk":"507783","name":"長井家住宅（梅屋）稲荷社","kana":"ながいけじゅうたく（うめや）いなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2495-1","lat":34.20663611,"lng":136.33954444,"geo_status":"db","era":"昭和44年頃","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0307","desc":"南蔵の西に南面して建つ屋敷社である。覆屋はコンクリート基礎に建つ切妻造桟瓦葺の妻入で、正面に上部格子の板扉を両開きに吊り込む。背面壁下部には狐が通う孔を穿つ。内部の祠は一間社流見世棚造で屋根は流し板葺である。敷地南方のアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013821"},{"id":"00013824","register_sub_id":"101","register_pk":"507786","name":"長井家住宅（梅屋）内門、内塀及び通用門","kana":"ながいけじゅうたく（うめや）うちもん、うちへいおよびつうようもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2495-3他","lat":34.20670556,"lng":136.33968889,"geo_status":"db","era":"昭和6年頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"内門 木造、瓦葺、間口1.5m、内塀 木造、銅板葺及び瓦葺、総延長31m、通用門 2.4m","structure_material":"内門 木造","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0310","desc":"主庭の東を限る内塀である。主屋東面の座敷北から東へ延び、北半は竪板張に板欄間を設け銅板葺、南半は竪板張に格子窓を開き桟瓦葺とする。北辺の内門は屋根を切上げ、板扉の両開きとする。南辺の通用門は格子付板戸の引違である。主庭の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013824"},{"id":"00013813","register_sub_id":"101","register_pk":"507775","name":"長井家住宅（梅屋）主屋","kana":"ながいけじゅうたく（うめや）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2495-1","lat":34.20683333,"lng":136.33948889,"geo_status":"db","era":"江戸末期／昭和6年増築・同48年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積270㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0299","desc":"紀伊長島港近くに宅地を構える林業家の住宅。切妻造桟瓦葺の南北棟で東正面から南面座敷へ下屋を廻す。玄関南の取次の間に地袋棚を設け、南東角が八畳座敷で西に仏間が並ぶ。柱や差物は木柄が大きく、吟味した良材による丁寧な造作の大規模な主屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013813"},{"id":"00013819","register_sub_id":"101","register_pk":"507781","name":"長井家住宅（梅屋）事務所棟","kana":"ながいけじゅうたく（うめや）じむしょとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2496-2他","lat":34.20686111,"lng":136.33923889,"geo_status":"db","era":"明治中期／昭和42年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0305","desc":"敷地北辺、西蔵の下屋の東に接続する平屋建で、入母屋造桟瓦葺である。北壁は漆喰塗で腰を竪板張とする。南面に庇がつく。西室が踏込土間のある板敷の事務室で、東室は休憩室で三畳と流しのある土間からなる。東端は便所と物置である。北面景観の要をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013819"},{"id":"00013820","register_sub_id":"101","register_pk":"507782","name":"長井家住宅（梅屋）女中部屋","kana":"ながいけじゅうたく（うめや）じょちゅうべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2495-1","lat":34.20695,"lng":136.33941944,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0306","desc":"敷地北辺、主屋の北に建つ平屋建で東半の東妻は寄棟造、西妻と西半の落棟は切妻造で桟瓦葺とする。外壁は漆喰塗で腰を竪板張とし、東面に出格子窓を付ける。東半六畳を女中部屋とし、西の落棟は土間の家事室で氷式冷蔵庫を設置する。北面景観の要をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013820"},{"id":"00013822","register_sub_id":"101","register_pk":"507784","name":"長井家住宅（梅屋）正門及び石積","kana":"ながいけじゅうたく（うめや）せいもんおよびいしづみ","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2518他","lat":34.206825,"lng":136.3398,"geo_status":"db","era":"石積：昭和6年頃 正門：昭和44年頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"正門 鉄筋コンクリート造門柱、間口3.6m、石積 総延長42m","structure_material":"正門 鉄筋コンクリート造門柱","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0308","desc":"正門は東蔵の南で東側道路に開く。道路から三メートル程引いて間口三・六メートルに高さ二・一メートルの鉄筋コンクリート造角柱一対を立て両開き門扉を吊る。正門から南北に延びる石積は上部を生垣とする。大振りの石を野面積とし、豪壮な景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013822"},{"id":"00013823","register_sub_id":"101","register_pk":"507785","name":"長井家住宅（梅屋）外塀及び通用門","kana":"ながいけじゅうたく（うめや）そとべいおよびつうようもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2495-1他","lat":34.20696111,"lng":136.33955278,"geo_status":"db","era":"昭和6年頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"外塀 木造、瓦葺、延長26m、通用門 間口2.1m","structure_material":"外塀 木造","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0309","desc":"敷地北辺を限る塀と門で、女中部屋の東妻から東へ延びて通用門部を凹ませ、南へ折れて東蔵の北西角に取付く。コンクリート布基礎上に切石を据えて柱を立てる。桟瓦葺屋根は腕木で受ける。通用門は格子戸引違で表裏に板庇をつける。端正な景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013823"},{"id":"00013818","register_sub_id":"101","register_pk":"507780","name":"長井家住宅（梅屋）西蔵","kana":"ながいけじゅうたく（うめや）にしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2496-2","lat":34.20680278,"lng":136.33915278,"geo_status":"db","era":"江戸末期／明治中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0304","desc":"主屋の西方、離れの北に建つ土蔵造二階建で、什器等を納める。切妻造桟瓦葺の南北棟で東面に吹放しの下屋がつく。鉢巻は漆喰塗、外壁は簓子下見板張で腰を竪板張とする。小屋組は登梁形式で、挟み梁を加えて補強している。敷地北西の景観の主要素をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013818"},{"id":"00013814","register_sub_id":"101","register_pk":"507776","name":"長井家住宅（梅屋）離れ","kana":"ながいけじゅうたく（うめや）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2496-3","lat":34.20671389,"lng":136.33924167,"geo_status":"db","era":"昭和7年頃／昭和44年増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積129㎡","structure_material":"木造平屋一部2階建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0300","desc":"主屋の西方に建つ木造二階建で寄棟造桟瓦葺とする。一階は南西が座敷八畳で東に次の間六畳をおく。二階は八畳茶室で丸柱に面皮の長押を打つ数寄屋普請である。東の平屋建は昭和四四年増築のＬＤＫで南面を開放的に扱う。良質な住空間を供する隠居家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013814"},{"id":"00013817","register_sub_id":"101","register_pk":"507779","name":"長井家住宅（梅屋）東蔵","kana":"ながいけじゅうたく（うめや）ひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2519","lat":34.20693056,"lng":136.339725,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積91㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0303","desc":"主屋の東に前庭を挟んで建つ土蔵造二階建で、切妻造桟瓦葺の南北棟である。西面に下屋を付け二所の戸口を開く。一階北室は北半が土間で南半を板敷、南室は板敷とし、独立柱を立て小屋を受ける。農具や林業道具の納屋であった。敷地北東の景観の主要素をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013817"},{"id":"00013816","register_sub_id":"101","register_pk":"507778","name":"長井家住宅（梅屋）南蔵","kana":"ながいけじゅうたく（うめや）みなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2495-1","lat":34.20665278,"lng":136.339625,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0302","desc":"主屋南に主庭を挟んで建つ土蔵造二階建の家財蔵で、切妻造本瓦葺。鉢巻は漆喰塗で壁面上部は竪板張、下部は簓子下見板張とする。北妻の戸前は桟瓦葺でガラス障子戸を建込む。戸口は漆喰塗扉の両開きである。小屋組は登梁形式とする。南からの景観の要をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013816"},{"id":"00013815","register_sub_id":"101","register_pk":"507777","name":"長井家住宅（梅屋）渡り廊下","kana":"ながいけじゅうたく（うめや）わたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県北牟婁郡紀北町東長島字呼崎2495-1","lat":34.20661389,"lng":136.33949444,"geo_status":"db","era":"昭和6年頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0301","desc":"主屋南の便所から南へ延び、東へ折れて南蔵北の戸前へ取付く渡り廊下で、主庭の南西を限る。切妻造の桟瓦葺とする。主庭側は丸柱を立てて吹放しとし、西面と南面の土壁は大津壁で上部を木格子窓とし、外面の腰は色モルタル掻落とする。主庭の景観を調える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013815"},{"id":"00010313","register_sub_id":"101","register_pk":"199086","name":"中森家住宅井戸屋形及び板塀","kana":"なかもりけじゅうたくいどやかたおよびいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊賀市上野玄蕃町195","lat":34.76885,"lng":136.133498,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"井戸屋形 木造、瓦葺、面積12㎡、井戸付 板塀 木造、瓦葺、延長7.0m","structure_material":"井戸屋形 木造","registered":"2014.12.19(平成26.12.19)","register_no":"24-0186","desc":"主屋西側に建つ井戸屋形は切妻造桟瓦葺で、西半を板壁で囲む井戸屋として石製井戸枠を据え、東半は飛び石を並べた通路とする。井戸屋形の東西に出入口、南に小窓を設ける。井戸屋形北西隅から蔵の間をつなぐ板塀が中庭と外庭を画し、風情ある庭空間を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010313"},{"id":"00010312","register_sub_id":"101","register_pk":"199085","name":"中森家住宅蔵","kana":"なかもりけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊賀市上野玄蕃町195","lat":34.768876,"lng":136.13338,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"24-0185","desc":"敷地西端、旧上野城外堀位置にあたる擁壁際に南北棟で建つ。土蔵造二階建、切妻造本瓦葺で南西面に下屋を設け、南面を出入口とする。外壁は鉢巻まで鉄板で養生し南妻に窓をあける。小屋は登り梁形式である。建ちの高い土蔵で、旧外堀からの屋敷景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010312"},{"id":"00010309","register_sub_id":"101","register_pk":"199082","name":"中森家住宅主屋","kana":"なかもりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊賀市上野玄蕃町195","lat":34.768861,"lng":136.133614,"geo_status":"db","era":"江戸末期／昭和前期・昭和50年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積106㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"24-0182","desc":"旧武家町の、通りに東面する敷地の東寄りに建つ。木造平屋建、切妻造桟瓦葺で下屋を廻らす。南妻の玄関脇を台所とし、奥寄りに、質実な造作のトコと棚を備えた八畳主室と、仏間付の六畳など四室を食い違いに配する。上野城下における武家住宅の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010309"},{"id":"00010310","register_sub_id":"101","register_pk":"199083","name":"中森家住宅離れ","kana":"なかもりけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊賀市上野玄蕃町195","lat":34.76892,"lng":136.133458,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"24-0183","desc":"主屋北西側に渡り廊下を介して東西棟で建ち、木造平屋建、切妻造桟瓦葺とし、下屋を廻らす。六畳二室を東西に並べて南東面に縁側を廻らし、開放的な形式とする。西室に設えたトコ、棚、付書院は大正期らしい洗練さを備え、旧武家住宅の近代における変容を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010310"},{"id":"00010311","register_sub_id":"101","register_pk":"199084","name":"中森家住宅前蔵","kana":"なかもりけじゅうたくまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊賀市上野玄蕃町195","lat":34.768819,"lng":136.133664,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積9.1㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"24-0184","desc":"敷地の南東隅に南北棟で建つ。土蔵造平屋建、桁行梁間とも三・〇メートル、切妻造桟瓦葺で、西面中央の戸口に庇を付ける。外壁は腰高に竪板を張り、上部を漆喰塗込め及び鉄板張とする。通りに面する土蔵で、門及び土塀と並び、歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010311"},{"id":"00010314","register_sub_id":"101","register_pk":"199087","name":"中森家住宅門及び土塀","kana":"なかもりけじゅうたくもんおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊賀市上野玄蕃町195","lat":34.769176,"lng":136.133469,"geo_status":"geocoded","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"門 木造、瓦葺、間口1.8m、潜戸付 土塀 土塀、瓦葺、延長9.9m","structure_material":"門 木造","registered":"2014.12.19(平成26.12.19)","register_no":"24-0187","desc":"敷地東面、前蔵北側に構える門と、北に延びる土塀で、いずれも切妻造桟瓦葺である。門は間口一・八メートルの一間腕木門で板扉を吊り、前蔵との間に潜戸を開く。土塀は延長一〇メートルで壁面を土壁仕上げとする。前蔵と共に武家屋敷の表構えに風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010314"},{"id":"00012750","register_sub_id":"101","register_pk":"367653","name":"服部家住宅表門","kana":"はっとりけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市小杉町字井塚604","lat":34.99420889,"lng":136.60976778,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、間口1.6m","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"24 － 266","desc":"敷地北面の道路沿いに建つ。やや建ちの高い切妻造桟瓦葺の四脚門で、中央の門口に引分け格子戸を備える。壁は大津壁風の卵黄色仕上で、腰に幅広の杉一枚板を張る。門口の垂壁上部見切に梁状の曲り材、欄間に埋もれ木を用いるなど細部に凝った造作をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012750"},{"id":"00012747","register_sub_id":"101","register_pk":"367650","name":"服部家住宅主屋","kana":"はっとりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市小杉町字井塚604他","lat":34.99420889,"lng":136.60976778,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積300㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"24 － 263","desc":"海蔵川南岸にある米穀商の住宅。主屋は敷地中央に北面して建つ起り屋根の入母屋造桟瓦葺、総二階建の東西に平屋棟を付し、外壁を杉皮張とする。一階に数寄屋風、二階に書院造風の座敷を配し、応接間や食堂は洋室とする。良材を多用した上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012747"},{"id":"00012749","register_sub_id":"101","register_pk":"367652","name":"服部家住宅土蔵","kana":"はっとりけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市小杉町字井塚604他","lat":34.99420889,"lng":136.60976778,"geo_status":"db","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"24 － 265","desc":"敷地西北隅に建つ家財蔵。渡廊下で主屋と接続する。土蔵造二階建、切妻造桟瓦葺で南面西寄りの下屋を蔵前とし、金庫用の扉口を備える。伝統形式を踏襲しつつ、外壁モルタルの洗出しや刷毛引きの仕上、小屋組の火打付トラスなど要所に近代的技法を取り入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012749"},{"id":"00012748","register_sub_id":"101","register_pk":"367651","name":"服部家住宅納屋","kana":"はっとりけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市小杉町字井塚604他","lat":34.99420889,"lng":136.60976778,"geo_status":"db","era":"昭和13年頃／昭和後期改築","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"24 － 264","desc":"主屋の前方、表門の東側に建つ。西半は書生室の計画だったが一室土間の納屋として完成した。桁行三間梁間二間、入母屋造桟瓦葺の平屋建で、外壁は腰高の杉皮張とし、東面の出入口に銅板葺庇を付し、西面窓を出窓とするなど、主屋と調和する丁寧な造作をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012748"},{"id":"00014855","register_sub_id":"101","register_pk":"519115","name":"星家住宅主屋","kana":"ほしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野小玉町3081-1","lat":34.76511667,"lng":136.12875556,"geo_status":"db","era":"明治40年頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"24 - 0331","desc":"上野旧城下町の中心部の辻角に建つ町家。つし二階建入母屋造妻入桟瓦葺。一階は出隅に格子を廻らし、二階は真壁で格子窓を開ける。内部は南西を玄関土間とした東西棟で床上に二列六室を配し、南東を床構え付き座敷とする。角地の入母屋造屋根が目を惹く町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014855"},{"id":"00010611","register_sub_id":"101","register_pk":"201185","name":"丸岡家住宅主屋","kana":"まるおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市宮町1-115","lat":34.492736,"lng":136.700389,"geo_status":"db","era":"慶応2年（1866）","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0202","desc":"伊勢講の御師丸岡宗大夫の住宅で、通りに面する長屋門から前庭を控えて東面する。正面南寄りに式台玄関を構えて七畳半を配し、かつては南側に客室を連ねた。北側は広い台所や床付の八畳など、内向きの居室を配置する。伊勢の御師住宅として希少価値が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010611"},{"id":"00010612","register_sub_id":"101","register_pk":"201186","name":"丸岡家住宅長屋門及び築地塀","kana":"まるおかけじゅうたくながやもんおよびついじべい","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市宮町1-115","lat":34.492736,"lng":136.700477,"geo_status":"db","era":"慶応2年（1866）","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"長屋門 木造平屋建、瓦葺、建築面積67㎡ 築地塀 土塀、瓦葺、延長6.7m","structure_material":"長屋門 木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0203","desc":"敷地東辺に建つ長屋門。主屋の式台正面を門口として堅牢な扉を吊り、北側に六畳二室と三畳を並べ、北端の四畳と土間で主屋台所と接続する。真壁漆喰塗で腰に簓子下見板を張る。築地塀は熨斗瓦を密に積む土塀で桟瓦を葺く。御師住宅の屋敷構えを伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010612"},{"id":"00010622","register_sub_id":"101","register_pk":"201196","name":"見世土井家住宅井戸屋形","kana":"みせどいけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県尾鷲市朝日町72","lat":34.072911,"lng":136.197891,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、面積10㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"24－0213","desc":"主主屋の北側、土間台所の勝手口を出た正面に東西棟で建つ。桁行三・七メートル梁間二・七メートル、木造平屋建、切妻造桟瓦葺。上屋は柱を四方転びに立て、西側のみ北通用門等からの目隠しの外壁板張とし、三方吹放しとする。内部に井戸と外流しを配置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010622"},{"id":"00010624","register_sub_id":"101","register_pk":"201198","name":"見世土井家住宅北通用門及び土塀","kana":"みせどいけじゅうたくきたつうようもんおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県尾鷲市朝日町79-2","lat":34.073008,"lng":136.197973,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"北通用門 木造、瓦葺、間口1.8m、袖塀及び潜り付 土塀 土塀、瓦葺、延長23m","structure_material":"北通用門 木造","registered":"2015.08.04(平成27.08.04)","register_no":"24－0215","desc":"敷地北辺に東西棟で建つ、間口一・八メートルの腕木門で、背面に控えの斜材を立てる。切妻造桟瓦葺、屋根付の両袖塀付で西側には潜戸が付く。通用門の東側には土塀が設けられ、花崗岩の石積、屋根は桟瓦葺とする。敷地北辺の伝統的な街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010624"},{"id":"00010618","register_sub_id":"101","register_pk":"201192","name":"見世土井家住宅蔵","kana":"みせどいけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県尾鷲市朝日町72","lat":34.072858,"lng":136.197884,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0209","desc":"主屋の西側に近接して東西棟で建つ。桁行五・五メートル梁間四・六メートル、土蔵造二階建、切妻造桟瓦葺で、鬼瓦に当家の屋号のひとつ「山吉」を飾り、軒瓦には家紋の八つ槌車を配する。東妻面に戸口を設け、庇を差出して奥行二・〇メートルの蔵前をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010618"},{"id":"00010620","register_sub_id":"101","register_pk":"201194","name":"見世土井家住宅米蔵","kana":"みせどいけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県尾鷲市朝日町72","lat":34.072986,"lng":136.197748,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0211","desc":"主屋の北西側、敷地の北西端に東西棟で建つ。桁行一一メートル梁間五・五メートル、土蔵造二階建、寄棟造桟瓦葺で、鬼瓦に家紋の八つ槌車を飾る。南面に戸口を設け、庇を差出して奥行二・七メートルの蔵前をとる。もとは上下階ともに米が保管されていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010620"},{"id":"00010616","register_sub_id":"101","register_pk":"201190","name":"見世土井家住宅主屋","kana":"みせどいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県尾鷲市朝日町72","lat":34.07281,"lng":136.198124,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積424㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0207","desc":"旧熊野街道に面する山林経営家の住宅。主屋は東西に長く、東端の玄関廻りを洋風意匠として脇に応接間を附属する。西側は和室を並べるが、数寄屋座敷の客間と夫人室を中廊下で仕切るなど時代的特徴を示す。細部にアールデコ意匠を取り入れた、上質な近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010616"},{"id":"00010623","register_sub_id":"101","register_pk":"201197","name":"見世土井家住宅正門及び塀","kana":"みせどいけじゅうたくせいもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県尾鷲市朝日町72他","lat":34.072682,"lng":136.198116,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"正門 鉄筋コンクリート造、間口2.9m 塀 鉄筋コンクリート造、総延長126m","structure_material":"正門 鉄筋コンクリート造","registered":"2015.08.04(平成27.08.04)","register_no":"24－0214","desc":"旧街道に面する敷地東辺の南側に正門、旧街道から派生する北側道路に通用門を開き、東辺、南辺、西辺の南側、北辺の東側に塀を廻らせる。塀外観は、主屋洋館部分と同様の色モルタル塗粗面仕上げで、門柱と正門廻りの塀下部をスクラッチタイル貼とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010623"},{"id":"00010621","register_sub_id":"101","register_pk":"201195","name":"見世土井家住宅外便所","kana":"みせどいけじゅうたくそとべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県尾鷲市朝日町72","lat":34.072968,"lng":136.19788,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積7.6㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0212","desc":"主屋の北西側、本蔵と米蔵の間に南北棟で建つ。桁行五・六メートル梁間一・四メートル、木造平屋建、切妻造桟瓦葺。東側からを戸口とし、西側には大和張の板塀を設け、北通用門等からの目隠しとする。もとは使用人専用便所と漬物保管場所として使用された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010621"},{"id":"00010619","register_sub_id":"101","register_pk":"201193","name":"見世土井家住宅納屋","kana":"みせどいけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県尾鷲市朝日町72","lat":34.072897,"lng":136.197734,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0210","desc":"蔵の西側に東西棟で建つ。桁行七・三メートル梁間三・六メートル、木造平屋建、切妻造桟瓦葺で軒先に雨除けの雁木を設ける。外壁は簓子下見板張で、南面に無双窓が設けられ室内換気が考慮されている。もとは炭部屋と呼ばれ、炭や農具等が保管されていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010619"},{"id":"00010617","register_sub_id":"101","register_pk":"201191","name":"見世土井家住宅本蔵","kana":"みせどいけじゅうたくほんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県尾鷲市朝日町72","lat":34.072965,"lng":136.197945,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0208","desc":"主屋の北側に東西棟で建つ。桁行九・一メートル梁間六・五メートル、土蔵造二階建、切妻造本瓦葺で、鬼瓦に家紋の八つ槌車が入る。南面に戸口を設け、庇を張出す。内部は上下階とも板壁で二室に仕切る。もとは接客や生活用の茶碗や食器類等を保管した家財蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010617"},{"id":"00004259","register_sub_id":"101","register_pk":"105249","name":"海山町郷土資料館（向栄館）","kana":"みやまちょうきょうどしりょうかん（こうえいかん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県北牟婁郡紀北町海山区中里96","lat":34.138611,"lng":136.218689,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積330㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"24 － 0050","desc":"地元林業家が本邸脇に建設した別館。木造平屋建，桟瓦葺で，正面中央に玄関ポーチを付し，両端部を前方に突出し左右対称の構成とする。外廻りは下見板張で縦長上げ下げ窓を並べ，出入口軒廻りの瑤珞，軒持送りなど装飾を持ち，地方への洋風建築の浸透を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004259"},{"id":"00008710","register_sub_id":"101","register_pk":"149431","name":"森家住宅主屋","kana":"もりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県亀山市野村町807","lat":34.85564555,"lng":136.44436383,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0108","desc":"亀山宿・関宿間の野村集落に所在。切妻造桟瓦葺で、西面に切妻棟を付設、周囲に下屋をまわす。左手に土間、右手に居室を配し、さらに奥に座敷を設ける。妻を漆喰で塗り込め、正面は上屋を黒漆喰真壁、下屋に出格子を設けるなど、町家的な表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008710"},{"id":"00009305","register_sub_id":"101","register_pk":"194098","name":"森家住宅主屋","kana":"もりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市羽津町4110","lat":34.98861473,"lng":136.6362962,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積184㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"24 － 0121","desc":"東海道に西面して建つ。入母屋造妻入、桟瓦葺で、間口は五間半に及ぶ。正面に大戸口を設けて通り土間を通し、北側に二列居室を設け、さらに片入母屋の角屋を出して小座敷とする。近辺で類例の少ない妻入の大型町家で、東海道沿いの景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009305"}];
